import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Category = 
  | 'Food & Dining'
  | 'Transportation'
  | 'Shopping'
  | 'Entertainment'
  | 'Bills & Utilities'
  | 'Health'
  | 'Education'
  | 'Other';

export type Mood = 'Happy' | 'Stressed' | 'Tired' | 'Bored' | 'Excited' | 'Neutral';

export interface Transaction {
  id: string;
  amount: number;
  category: Category;
  date: string; // ISO string
  time: string; // HH:mm
  description: string;
  mood: Mood;
}

export interface BehavioralInsight {
  title: string;
  description: string;
  severity: 'neutral' | 'warning' | 'positive';
  type: 'pattern' | 'budget' | 'psychology';
}

export interface BudgetGoal {
  category: Category;
  limit: number;
}

import React from 'react';
import { 
  Utensils, 
  Car, 
  ShoppingBag, 
  Gamepad2, 
  Lightbulb, 
  HeartPulse, 
  GraduationCap, 
  MoreHorizontal 
} from 'lucide-react';
import { Category, Mood } from './types';

export const CATEGORIES: Category[] = [
  'Food & Dining',
  'Transportation',
  'Shopping',
  'Entertainment',
  'Bills & Utilities',
  'Health',
  'Education',
  'Other'
];

export const MOODS: Mood[] = ['Happy', 'Stressed', 'Tired', 'Bored', 'Excited', 'Neutral'];

export const CATEGORY_ICONS: Record<Category, React.ReactNode> = {
  'Food & Dining': <Utensils className="w-5 h-5" />,
  'Transportation': <Car className="w-5 h-5" />,
  'Shopping': <ShoppingBag className="w-5 h-5" />,
  'Entertainment': <Gamepad2 className="w-5 h-5" />,
  'Bills & Utilities': <Lightbulb className="w-5 h-5" />,
  'Health': <HeartPulse className="w-5 h-5" />,
  'Education': <GraduationCap className="w-5 h-5" />,
  'Other': <MoreHorizontal className="w-5 h-5" />
};

export const INITIAL_GOALS = [
  { category: 'Food & Dining', limit: 400 },
  { category: 'Entertainment', limit: 200 },
  { category: 'Shopping', limit: 300 },
];

import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, BehavioralInsight, BudgetGoal } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getBehavioralInsights = async (
  transactions: Transaction[],
  goals: BudgetGoal[]
): Promise<BehavioralInsight[]> => {
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze the following personal finance transactions and budget goals. 
    Provide 3 to 5 factual, neutral behavioral insights. 
    Focus on:
    1. Patterns related to time (e.g., late night spending).
    2. Psychological connections (e.g., spending correlated with mood).
    3. Budget comparison (e.g., specific category exceeding goals).

    Data:
    Transactions: ${JSON.stringify(transactions)}
    Budget Goals: ${JSON.stringify(goals)}

    Be precise. Instead of "You spend a lot on food", say "Food delivery spending increases after 9pm".
    Instead of "You shop when sad", say "Transaction volume for 'Shopping' is 30% higher on days marked as 'Stressed'".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { 
                type: Type.STRING, 
                description: 'Values: neutral, warning, positive' 
              },
              type: { 
                type: Type.STRING, 
                description: 'Values: pattern, budget, psychology' 
              }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    const result = JSON.parse(response.text || "[]");
    return result;
  } catch (error) {
    console.error("Error fetching insights:", error);
    return [{
      title: "Data Analysis Paused",
      description: "We're having trouble reaching the AI. Try again in a moment.",
      severity: "neutral",
      type: "pattern"
    }];
  }
};

import React, { useState } from 'react';
import { CATEGORIES, MOODS } from '../constants';
import { Transaction, Category, Mood } from '../types';
import { PlusCircle, X } from 'lucide-react';

interface Props {
  onAdd: (t: Transaction) => void;
  onClose: () => void;
}

const TransactionForm: React.FC<Props> = ({ onAdd, onClose }) => {
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [description, setDescription] = useState('');
  const [mood, setMood] = useState<Mood>('Neutral');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [time, setTime] = useState(new Date().toTimeString().slice(0, 5));

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || isNaN(Number(amount))) return;

    onAdd({
      id: Math.random().toString(36).substr(2, 9),
      amount: Number(amount),
      category,
      description,
      mood,
      date,
      time
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-gray-800">Log Transaction</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Amount</label>
            <div className="relative">
              <span className="absolute left-3 top-2.5 text-gray-500">$</span>
              <input
                required
                type="number"
                step="0.01"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                className="w-full pl-8 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                placeholder="0.00"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
              <input
                type="date"
                value={date}
                onChange={(e) => setDate(e.target.value)}
                className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Time</label>
              <input
                type="time"
                value={time}
                onChange={(e) => setTime(e.target.value)}
                className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value as Category)}
              className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500"
            >
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">How were you feeling?</label>
            <div className="flex flex-wrap gap-2">
              {MOODS.map(m => (
                <button
                  key={m}
                  type="button"
                  onClick={() => setMood(m)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
                    mood === m 
                      ? 'bg-blue-600 text-white shadow-md' 
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  }`}
                >
                  {m}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Description (Optional)</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm outline-none"
              placeholder="What did you buy?"
            />
          </div>

          <button
            type="submit"
            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-xl shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2 mt-4"
          >
            <PlusCircle className="w-5 h-5" />
            Save Transaction
          </button>
        </form>
      </div>
    </div>
  );
};

export default TransactionForm;

import React from 'react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  Legend 
} from 'recharts';
import { Transaction, Category } from '../types';

interface Props {
  transactions: Transaction[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#64748b', '#06b6d4'];

const Charts: React.FC<Props> = ({ transactions }) => {
  const categoryData = transactions.reduce((acc, curr) => {
    const existing = acc.find(item => item.name === curr.category);
    if (existing) {
      existing.value += curr.amount;
    } else {
      acc.push({ name: curr.category, value: curr.amount });
    }
    return acc;
  }, [] as { name: Category; value: number }[]);

  // Simple daily aggregation for the bar chart
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return d.toISOString().split('T')[0];
  }).reverse();

  const dailyData = last7Days.map(date => {
    const total = transactions
      .filter(t => t.date === date)
      .reduce((sum, t) => sum + t.amount, 0);
    return {
      name: new Date(date).toLocaleDateString(undefined, { weekday: 'short' }),
      amount: total
    };
  });

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-80">
        <h3 className="text-sm font-semibold text-gray-500 mb-4 uppercase tracking-wider">Spending by Category</h3>
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={categoryData}
              innerRadius={60}
              outerRadius={80}
              paddingAngle={5}
              dataKey="value"
            >
              {categoryData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip 
              formatter={(value: number) => `$${value.toFixed(2)}`}
              contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
            />
            <Legend verticalAlign="bottom" height={36}/>
          </PieChart>
        </ResponsiveContainer>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-80">
        <h3 className="text-sm font-semibold text-gray-500 mb-4 uppercase tracking-wider">Daily Trend (Last 7 Days)</h3>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={dailyData}>
            <XAxis dataKey="name" axisLine={false} tickLine={false} />
            <YAxis hide />
            <Tooltip 
              formatter={(value: number) => `$${value.toFixed(2)}`}
              cursor={{ fill: '#f3f4f6' }}
              contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
            />
            <Bar dataKey="amount" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={32} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default Charts;

import React from 'react';
