import React, { useState, useEffect, useCallback } from 'react';
import { Transaction, BehavioralInsight, BudgetGoal } from './types';
import { INITIAL_GOALS } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import { getBehavioralInsights } from './services/geminiService';
import { 
  Wallet, 
  Plus, 
  LayoutDashboard, 
  History, 
  Target,
  ArrowUpRight,
  ArrowDownRight,
  CreditCard
} from 'lucide-react';

const MOCK_DATA: Transaction[] = [
  { id: '1', amount: 45.50, category: 'Food & Dining', date: '2023-11-20', time: '21:15', description: 'Uber Eats', mood: 'Tired' },
  { id: '2', amount: 120.00, category: 'Entertainment', date: '2023-11-19', time: '14:00', description: 'Movie Night', mood: 'Happy' },
  { id: '3', amount: 85.00, category: 'Shopping', date: '2023-11-18', time: '18:30', description: 'New Shoes', mood: 'Stressed' },
  { id: '4', amount: 32.00, category: 'Food & Dining', date: '2023-11-20', time: '22:45', description: 'Midnight Pizza', mood: 'Bored' },
];

const App: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('fin_transactions');
    return saved ? JSON.parse(saved) : MOCK_DATA;
  });

  const [goals] = useState<BudgetGoal[]>(INITIAL_GOALS);
  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    localStorage.setItem('fin_transactions', JSON.stringify(transactions));
  }, [transactions]);

  const refreshInsights = useCallback(async () => {
    if (transactions.length === 0) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals]);

  useEffect(() => {
    // Initial load of insights
    refreshInsights();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const addTransaction = (t: Transaction) => {
    setTransactions(prev => [t, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const totalSpent = transactions.reduce((acc, curr) => acc + curr.amount, 0);
  const avgTransaction = transactions.length > 0 ? totalSpent / transactions.length : 0;

  return (
    <div className="min-h-screen pb-20 lg:pb-0">
      {/* Sidebar Navigation (Desktop) */}
      <nav className="fixed left-0 top-0 h-full w-64 bg-white border-r border-gray-100 p-6 hidden lg:block">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">FinSense AI</span>
        </div>

        <div className="space-y-1">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" active />
          <NavLink icon={<History className="w-5 h-5" />} label="History" />
          <NavLink icon={<Target className="w-5 h-5" />} label="Budgets" />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label="Accounts" />
        </div>

        <div className="mt-auto absolute bottom-8 left-6 right-6">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl p-4 text-white shadow-xl">
            <p className="text-xs text-blue-100 font-medium mb-1">Pro Account</p>
            <p className="text-sm font-semibold mb-3">AI Analysis Unlimited</p>
