import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Transaction, BehavioralInsight, BudgetGoal, Currency, Account, Category, AccountType } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import { getBehavioralInsights } from './services/geminiService';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, ArrowUpRight, ArrowDownRight, 
  CreditCard, Search, TrendingUp, X, Trash2, PiggyBank, Globe
} from 'lucide-react';

type ViewType = 'dashboard' | 'history' | 'budgets' | 'accounts';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [showForm, setShowForm] = useState(false);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);

  // Persistence
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('fin_transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [goals, setGoals] = useState<BudgetGoal[]>(() => {
    const saved = localStorage.getItem('fin_goals');
    return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
    const saved = localStorage.getItem('fin_accounts');
    return saved ? JSON.parse(saved) : [
      { id: 'acc1', name: 'Main Bank', type: 'Checking', balance: 5000 },
      { id: 'acc2', name: 'Savings Account', type: 'Savings', balance: 12000 }
    ];
  });

  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);

  useEffect(() => {
    localStorage.setItem('fin_transactions', JSON.stringify(transactions));
    localStorage.setItem('fin_goals', JSON.stringify(goals));
    localStorage.setItem('fin_accounts', JSON.stringify(accounts));
  }, [transactions, goals, accounts]);

  const refreshInsights = useCallback(async () => {
    if (transactions.length === 0) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals]);

  useEffect(() => {
    refreshInsights();
  }, [refreshInsights]);

  const formatMoney = (amount: number) => {
    return `${currency.symbol}${amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalSpent = useMemo(() => transactions.reduce((acc, curr) => acc + curr.amount, 0), [transactions]);
  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Views
  const renderDashboard = () => (
    <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <StatCard title="Total Spending" value={formatMoney(totalSpent)} trend="+12.5%" trendType="down" icon={<Wallet className="w-5 h-5" />} />
        <StatCard title="Total Assets" value={formatMoney(totalBalance)} trend="+2.1%" trendType="up" icon={<TrendingUp className="w-5 h-5" />} />
        <StatCard title="Budgets" value={`${goals.length}`} trend="Active" trendType="up" icon={<Target className="w-5 h-5" />} />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 mb-8">
        <div className="xl:col-span-2 space-y-8">
          <Charts transactions={transactions} />
          <div className="hidden xl:block">
            <h3 className="text-lg font-bold text-gray-800 mb-4">Recent Activity</h3>
            <TransactionList transactions={transactions.slice(0, 5)} onDelete={(id) => setTransactions(t => t.filter(x => x.id !== id))} />
          </div>
        </div>
        <div className="xl:col-span-1">
          <AIInsights insights={insights} loading={loadingInsights} onRefresh={refreshInsights} />
        </div>
      </div>
    </div>
  );

  const renderHistory = () => (
    <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <h2 className="text-xl font-bold text-gray-800">Transaction History</h2>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Search..." className="pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-xl text-sm outline-none w-full md:w-64" />
        </div>
      </div>
      <TransactionList transactions={transactions} onDelete={(id) => setTransactions(t => t.filter(x => x.id !== id))} />
    </div>
  );

  const renderBudgets = () => (
    <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-800">Budget Goals</h2>
        <button onClick={() => setShowBudgetForm(true)} className="text-blue-600 hover:text-blue-700 font-bold flex items-center gap-1 text-sm bg-blue-50 px-3 py-1.5 rounded-lg transition-colors">
          <Plus className="w-4 h-4" /> Add Budget
        </button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {goals.map((goal) => {
          const spent = transactions.filter(t => t.category === goal.category).reduce((sum, t) => sum + t.amount, 0);
          const percent = Math.min((spent / goal.limit) * 100, 100);
          return (
            <div key={goal.id} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 group">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">{CATEGORY_ICONS[goal.category]}</div>
                  <h3 className="font-bold text-gray-800">{goal.category}</h3>
                </div>
                <button onClick={() => setGoals(g => g.filter(x => x.id !== goal.id))} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
              <div className="flex justify-between text-sm mb-2">
                <span className="text-gray-500">Spent: <span className="text-gray-900 font-semibold">{formatMoney(spent)}</span></span>
                <span className="text-gray-500">Limit: <span className="text-gray-900 font-semibold">{formatMoney(goal.limit)}</span></span>
              </div>
              <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                <div className={`h-full transition-all duration-1000 ${percent > 90 ? 'bg-rose-500' : 'bg-blue-600'}`} style={{ width: `${percent}%` }} />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  const renderAccounts = () => (
    <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-800">Financial Accounts</h2>
        <button onClick={() => setShowAccountForm(true)} className="text-blue-600 hover:text-blue-700 font-bold flex items-center gap-1 text-sm bg-blue-50 px-3 py-1.5 rounded-lg">
          <Plus className="w-4 h-4" /> Add Account
        </button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map(acc => (
          <div key={acc.id} className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-[1.5rem] text-white shadow-xl relative overflow-hidden group">
            <div className="absolute -top-4 -right-4 opacity-10 rotate-12 group-hover:rotate-0 transition-transform duration-500">
               <CreditCard className="w-32 h-32" />
            </div>
            <div className="relative z-10 flex flex-col h-full">
              <div className="flex justify-between items-start mb-8">
                <div>
                  <p className="text-blue-100 text-[10px] uppercase font-bold tracking-widest">{acc.type}</p>
                  <h3 className="font-bold text-lg">{acc.name}</h3>
                </div>
                <button onClick={() => setAccounts(a => a.filter(x => x.id !== acc.id))} className="p-1 hover:bg-white/20 rounded">
                  <X className="w-4 h-4" />
                </button>
              </div>
              <p className="text-3xl font-bold mb-2">{formatMoney(acc.balance)}</p>
              <p className="text-[10px] text-blue-200 uppercase tracking-widest mt-auto font-medium">Card ending **** {acc.id.slice(-4)}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-20 lg:pb-0">
      <nav className="fixed left-0 top-0 h-full w-64 bg-white border-r border-gray-100 p-6 hidden lg:block">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">FinSense AI</span>
        </div>
        <div className="space-y-1">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label="History" active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label="Budgets" active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label="Accounts" active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
        </div>
        <div className="mt-auto absolute bottom-8 left-6 right-6 p-4 bg-gray-50 rounded-2xl flex items-center gap-3">
           <Globe className="w-4 h-4 text-gray-400" />
           <select 
             value={currency.code} 
             onChange={(e) => setCurrency(CURRENCIES.find(c => c.code === e.target.value) || CURRENCIES[0])}
             className="bg-transparent text-xs font-bold text-gray-600 outline-none w-full"
           >
             {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label}</option>)}
           </select>
        </div>
      </nav>

      <main className="lg:ml-64 p-4 lg:p-8 max-w-7xl mx-auto min-h-screen">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-2xl font-bold text-gray-800 capitalize">{activeView}</h1>
            <p className="text-sm text-gray-500">Viewing your data in {currency.code} ({currency.symbol})</p>
          </div>
          <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl font-semibold shadow-lg shadow-blue-100 active:scale-95 transition-all">
            <Plus className="w-5 h-5" /> <span className="hidden sm:inline">Add Transaction</span>
          </button>
        </header>

        {activeView === 'dashboard' && renderDashboard()}
        {activeView === 'history' && renderHistory()}
        {activeView === 'budgets' && renderBudgets()}
        {activeView === 'accounts' && renderAccounts()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 px-4 py-2 flex justify-around items-center lg:hidden z-40 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
        <MobileNavLink icon={<LayoutDashboard className="w-5 h-5" />} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
        <MobileNavLink icon={<History className="w-5 h-5" />} active={activeView === 'history'} onClick={() => setActiveView('history')} />
        <button onClick={() => setShowForm(true)} className="w-12 h-12 bg-blue-600 text-white rounded-2xl shadow-lg flex items-center justify-center -translate-y-4 active:scale-90"><Plus className="w-6 h-6" /></button>
        <MobileNavLink icon={<Target className="w-5 h-5" />} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
        <MobileNavLink icon={<CreditCard className="w-5 h-5" />} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
      </nav>

      {showForm && <TransactionForm onAdd={(t) => setTransactions(prev => [t, ...prev])} onClose={() => setShowForm(false)} />}
      {showBudgetForm && <BudgetForm onAdd={(b) => setGoals(prev => [...prev, b])} onClose={() => setShowBudgetForm(false)} />}
      {showAccountForm && <AccountForm onAdd={(a) => setAccounts(prev => [...prev, a])} onClose={() => setShowAccountForm(false)} />}
    </div>
  );
};

const NavLink = ({ icon, label, active, onClick }: { icon: React.ReactNode; label: string; active: boolean; onClick: () => void }) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${active ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-500 hover:bg-gray-50 hover:text-gray-900'}`}>{icon}{label}</button>
);

const MobileNavLink = ({ icon, active, onClick }: { icon: React.ReactNode; active: boolean; onClick: () => void }) => (
  <button onClick={onClick} className={`p-3 rounded-xl transition-all ${active ? 'text-blue-600 bg-blue-50' : 'text-gray-400'}`}>{icon}</button>
);

const StatCard = ({ title, value, trend, trendType, icon }: { title: string; value: string; trend: string; trendType: 'up' | 'down'; icon: React.ReactNode }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex items-start justify-between">
    <div>
      <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">{title}</p>
      <h3 className="text-2xl font-bold text-gray-900 mb-2">{value}</h3>
      <div className={`flex items-center gap-1 text-xs font-bold ${trendType === 'up' ? 'text-emerald-500' : 'text-blue-500'}`}>{trend} <span className="text-gray-400 font-medium">trend</span></div>
    </div>
    <div className="p-3 bg-gray-50 rounded-xl text-gray-500">{icon}</div>
  </div>
);

const BudgetForm = ({ onAdd, onClose }: { onAdd: (b: BudgetGoal) => void; onClose: () => void }) => {
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [limit, setLimit] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl p-6 w-full max-w-sm">
        <h2 className="text-xl font-bold mb-4">Add Budget Goal</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-1">Category</label>
            <select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full border p-2 rounded-lg">
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Monthly Limit</label>
            <input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full border p-2 rounded-lg" placeholder="500.00" />
          </div>
          <div className="flex gap-3 pt-2">
            <button onClick={onClose} className="flex-1 bg-gray-100 py-2 rounded-xl font-bold">Cancel</button>
            <button onClick={() => { onAdd({ id: Math.random().toString(), category, limit: Number(limit) }); onClose(); }} className="flex-1 bg-blue-600 text-white py-2 rounded-xl font-bold">Save Goal</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const AccountForm = ({ onAdd, onClose }: { onAdd: (a: Account) => void; onClose: () => void }) => {
  const [name, setName] = useState('');
