          <div>
            <label className="block text-sm font-medium mb-1">Type</label>
            <select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border p-2 rounded-lg">
              {['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(t => <option key={t} value={t}>{t}</option>)}
