import { 
  collection, 
  doc, 
  setDoc, 
  query, 
  deleteDoc, 
  onSnapshot,
  orderBy,
  updateDoc
} from "firebase/firestore";
import { db } from "../firebase";
import { Transaction, BudgetGoal, Account } from "../types";

export const dataService = {
  subscribeToUserData: (userId: string, type: 'transactions' | 'goals' | 'accounts', callback: (data: any[]) => void) => {
    try {
      const colRef = collection(db, "users", userId, type);
      const q = type === 'transactions' ? query(colRef, orderBy("date", "desc"), orderBy("time", "desc")) : colRef;

      return onSnapshot(q, (snapshot) => {
        const items = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        callback(items);
      }, (error) => {
        console.error(`Firestore subscription error (${type}). Check your Security Rules:`, error);
        callback([]); // Return empty list on error to keep UI stable
      });
    } catch (e) {
      console.error(`Failed to setup subscription for ${type}:`, e);
      return () => {};
    }
  },

  addTransaction: async (userId: string, transaction: Transaction) => {
    try {
      const docRef = doc(collection(db, "users", userId, "transactions"));
      return await setDoc(docRef, { ...transaction, id: docRef.id });
    } catch (e) {
      console.error("Failed to add transaction:", e);
      throw e;
    }
  },

  deleteTransaction: async (userId: string, transactionId: string) => {
    try {
      await deleteDoc(doc(db, "users", userId, "transactions", transactionId));
    } catch (e) {
      console.error("Failed to delete transaction:", e);
      throw e;
    }
  },

  saveAccount: async (userId: string, account: Account) => {
    try {
      const docRef = doc(db, "users", userId, "accounts", account.id);
      await setDoc(docRef, account);
    } catch (e) {
      console.error("Failed to save account:", e);
      throw e;
    }
  },

  deleteAccount: async (userId: string, accountId: string) => {
    try {
      await deleteDoc(doc(db, "users", userId, "accounts", accountId));
    } catch (e) {
      console.error("Failed to delete account:", e);
      throw e;
    }
  },

  updateAccountBalance: async (userId: string, accountId: string, newBalance: number) => {
    try {
      const docRef = doc(db, "users", userId, "accounts", accountId);
      await updateDoc(docRef, { balance: newBalance });
    } catch (e) {
      console.warn("Account balance sync failed (this is expected if account was deleted):", e);
    }
  },

  saveGoal: async (userId: string, goal: BudgetGoal) => {
    try {
      const docRef = doc(db, "users", userId, "goals", goal.id);
      await setDoc(docRef, goal);
    } catch (e) {
      console.error("Failed to save goal:", e);
      throw e;
    }
  },

  deleteGoal: async (userId: string, goalId: string) => {
    try {
      await deleteDoc(doc(db, "users", userId, "goals", goalId));
    } catch (e) {
      console.error("Failed to delete goal:", e);
      throw e;
    }
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, BehavioralInsight, BudgetGoal } from "../types";

export const getBehavioralInsights = async (
  transactions: Transaction[],
  goals: BudgetGoal[],
  lang: 'en' | 'ar' = 'en'
): Promise<BehavioralInsight[]> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    console.error("Gemini API Key is missing. Check your environment variables.");
    return [{
      title: lang === 'ar' ? "الذكاء الاصطناعي غير مفعل" : "AI Not Available",
      description: lang === 'ar' ? "يرجى التحقق من إعدادات مفتاح API الخاص بك." : "Please check your API Key settings to enable insights.",
      severity: "neutral",
      type: "pattern"
    }];
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze the following personal finance transactions and budget goals. 
    Provide 3 to 5 factual, neutral behavioral insights. 
    IMPORTANT: Provide the response in ${lang === 'ar' ? 'Arabic (العربية)' : 'English'}.

    Focus on:
    1. Patterns related to time (e.g., late night spending).
    2. Psychological connections (e.g., spending correlated with mood).
    3. Budget comparison (e.g., specific category exceeding goals).

    Data:
    Transactions: ${JSON.stringify(transactions)}
    Budget Goals: ${JSON.stringify(goals)}

    Be precise. Instead of "You spend a lot on food", say "Food delivery spending increases after 9pm".
    Instead of "You shop when sad", say "Transaction volume for 'Shopping' is 30% higher on days marked as 'Stressed'".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { 
                type: Type.STRING, 
                description: 'Values: neutral, warning, positive' 
              },
              type: { 
                type: Type.STRING, 
                description: 'Values: pattern, budget, psychology' 
              }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    const result = JSON.parse(response.text || "[]");
    return result;
  } catch (error) {
    console.error("Error fetching insights:", error);
    return [{
      title: lang === 'ar' ? "تحليل البيانات متوقف مؤقتاً" : "Data Analysis Paused",
      description: lang === 'ar' ? "نواجه مشكلة في الوصول للذكاء الاصطناعي. حاول مرة أخرى." : "We're having trouble reaching the AI. Try again in a moment.",
      severity: "neutral",
      type: "pattern"
    }];
  }
};

