import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BehavioralInsight, BudgetGoal, Currency, Account, Category, AccountType } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import AuthScreen from './components/AuthScreen';
import { getBehavioralInsights } from './services/geminiService';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  TrendingUp, Globe, Languages, LogOut, Settings
} from 'lucide-react';

type ViewType = 'dashboard' | 'history' | 'budgets' | 'accounts' | 'settings';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>(() => {
    const saved = localStorage.getItem('fin_lang');
    return (saved as Language) || 'en';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    const saved = localStorage.getItem('fin_currency');
    return saved ? JSON.parse(saved) : CURRENCIES[0];
  });

  const [showForm, setShowForm] = useState(false);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);

  // Firestore state
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (u) => {
      setUser(u);
      setAuthLoading(false);
    }, (error) => {
      console.error("Auth State Error:", error);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) {
      setTransactions([]);
      setGoals([]);
      setAccounts([]);
      return;
    }
    const unsubT = dataService.subscribeToUserData(user.uid, 'transactions', setTransactions);
    const unsubG = dataService.subscribeToUserData(user.uid, 'goals', setGoals);
    const unsubA = dataService.subscribeToUserData(user.uid, 'accounts', (data) => {
      if (data.length === 0) {
        const defaults: Account[] = [
          { id: 'acc1', name: 'Main Wallet', type: 'Checking', balance: 5000 },
          { id: 'acc2', name: 'Emergency Fund', type: 'Savings', balance: 12000 }
        ];
        defaults.forEach(acc => dataService.saveAccount(user.uid, acc));
      } else {
        setAccounts(data);
      }
    });
    return () => { unsubT(); unsubG(); unsubA(); };
  }, [user]);

  useEffect(() => {
    localStorage.setItem('fin_currency', JSON.stringify(currency));
    localStorage.setItem('fin_lang', lang);
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [currency, lang]);

  const refreshInsights = useCallback(async () => {
    if (transactions.length < 3) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals, lang);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals, lang]);

  useEffect(() => {
    if (user && transactions.length > 0) refreshInsights();
  }, [transactions.length, user, refreshInsights]);

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalSpent = useMemo(() => transactions.reduce((acc, curr) => acc + curr.amount, 0), [transactions]);
  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const handleLogout = async () => { await signOut(auth); };

  const addTransaction = async (entry: Transaction) => {
    if (!user) return;
    await dataService.addTransaction(user.uid, entry);
    const account = accounts.find(a => a.id === entry.accountId);
    if (account) {
      await dataService.updateAccountBalance(user.uid, account.id, account.balance - entry.amount);
    }
  };

  const deleteTransaction = async (id: string) => {
    if (!user) return;
    const target = transactions.find(x => x.id === id);
    if (target) {
      const account = accounts.find(a => a.id === target.accountId);
      if (account) await dataService.updateAccountBalance(user.uid, account.id, account.balance + target.amount);
    }
    await dataService.deleteTransaction(user.uid, id);
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#f8fafc]">
        <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-gray-400 font-medium animate-pulse">Initializing FinSense...</p>
      </div>
    );
  }

  if (!user) return <AuthScreen lang={lang} />;

  const renderSettings = () => (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6 max-w-lg mx-auto">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <Settings className="w-5 h-5 text-blue-600" /> {lang === 'ar' ? 'الإعدادات' : 'Settings'}
        </h2>

        <div className="space-y-6">
          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2">
              <Languages className="w-3.5 h-3.5" /> {t.language}
            </label>
            <div className="flex gap-2 bg-gray-50 p-1.5 rounded-2xl border border-gray-100">
              <button onClick={() => setLang('en')} className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${lang === 'en' ? 'bg-white shadow-sm text-blue-600 border border-blue-50' : 'text-gray-400'}`}>English</button>
              <button onClick={() => setLang('ar')} className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${lang === 'ar' ? 'bg-white shadow-sm text-blue-600 border border-blue-50' : 'text-gray-400'}`}>العربية</button>
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2">
              <Globe className="w-3.5 h-3.5" /> {t.currency}
            </label>
            <select 
              value={JSON.stringify(currency)} 
              onChange={(e) => setCurrency(JSON.parse(e.target.value))}
              className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-gray-700 appearance-none"
            >
              {CURRENCIES.map(c => <option key={c.code} value={JSON.stringify(c)}>{c.label} ({c.symbol})</option>)}
            </select>
          </div>

          <div className="pt-6 border-t border-gray-100">
            <button 
              onClick={handleLogout}
              className="w-full flex items-center justify-center gap-3 p-4 bg-rose-50 text-rose-600 rounded-2xl transition-all font-bold text-sm border border-rose-100 hover:bg-rose-100"
            >
              <LogOut className="w-4 h-4" />
              {lang === 'ar' ? 'تسجيل الخروج' : 'Logout'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-[#f8fafc]" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      <nav className={`fixed ${lang === 'ar' ? 'right-0' : 'left-0'} top-0 h-full w-64 bg-white border-${lang === 'ar' ? 'l' : 'r'} border-gray-100 p-6 hidden lg:flex flex-col z-30`}>
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100"><Wallet className="w-6 h-6" /></div>
          <span className="text-xl font-black text-blue-600 tracking-tight">FinSense AI</span>
        </div>
        <div className="space-y-2">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label={t.overview} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label={t.history} active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label={t.budgets} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label={t.accounts} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
          <NavLink icon={<Settings className="w-5 h-5" />} label={lang === 'ar' ? 'الإعدادات' : 'Settings'} active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>
      </nav>

      <main className={`${lang === 'ar' ? 'lg:mr-64' : 'lg:ml-64'} p-4 lg:p-10 max-w-7xl mx-auto min-h-screen`}>
        <header className="flex justify-between items-center mb-10">
          <div>
            <h1 className="text-3xl font-black text-gray-900 capitalize tracking-tight">{(t as any)[activeView] || (lang === 'ar' ? 'الإعدادات' : 'Settings')}</h1>
            <p className="text-sm font-medium text-gray-400 mt-1">{currency.code} ({currency.symbol}) • {user.email || 'Guest'}</p>
          </div>
          <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-bold shadow-xl shadow-blue-100 active:scale-95 transition-all text-sm">
            <Plus className="w-5 h-5" /> <span className="hidden sm:inline">{t.entry}</span>
          </button>
        </header>

        {activeView === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              <StatCard title={t.total_expenses} value={formatMoney(totalSpent)} trend={t.trend_monthly} trendType="down" icon={<Wallet className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.total_assets} value={formatMoney(totalBalance)} trend={t.trend_liquid} trendType="up" icon={<TrendingUp className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.budget_health} value={`${goals.length}`} trend={t.trend_goals} trendType="up" icon={<Target className="w-5 h-5" />} lang={lang} />
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
              <div className="xl:col-span-2 space-y-8"><Charts transactions={transactions} /></div>
              <div className="xl:col-span-1"><AIInsights insights={insights} loading={loadingInsights} onRefresh={refreshInsights} lang={lang} /></div>
            </div>
          </div>
        )}
        {activeView === 'history' && <div className="animate-in fade-in slide-in-from-bottom-4 duration-500"><TransactionList transactions={transactions} onDelete={deleteTransaction} lang={lang} /></div>}
        {activeView === 'budgets' && <div className="animate-in fade-in slide-in-from-bottom-4 duration-500"><BudgetsView user={user} goals={goals} transactions={transactions} formatMoney={formatMoney} lang={lang} onAddClick={() => setShowBudgetForm(true)} /></div>}
        {activeView === 'accounts' && <div className="animate-in fade-in slide-in-from-bottom-4 duration-500"><AccountsView user={user} accounts={accounts} formatMoney={formatMoney} lang={lang} onAddClick={() => setShowAccountForm(true)} /></div>}
        {activeView === 'settings' && renderSettings()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-gray-100 px-4 py-3 flex justify-around items-center lg:hidden z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] rounded-t-[2.5rem]">
        <MobileNavLink icon={<LayoutDashboard className="w-6 h-6" />} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
        <MobileNavLink icon={<History className="w-6 h-6" />} active={activeView === 'history'} onClick={() => setActiveView('history')} />
        <button onClick={() => setShowForm(true)} className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center -translate-y-6 active:scale-90 transition-transform"><Plus className="w-7 h-7" /></button>
        <MobileNavLink icon={<Target className="w-6 h-6" />} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
        <MobileNavLink icon={<Settings className="w-6 h-6" />} active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
      </nav>

      {showForm && <TransactionForm accounts={accounts} onAdd={addTransaction} onClose={() => setShowForm(false)} lang={lang} />}
      {showBudgetForm && <BudgetForm onAdd={(b: any) => dataService.saveGoal(user.uid, b)} onClose={() => setShowBudgetForm(false)} lang={lang} />}
      {showAccountForm && <AccountForm onAdd={(a: any) => dataService.saveAccount(user.uid, a)} onClose={() => setShowAccountForm(false)} lang={lang} />}
    </div>
  );
};

const NavLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold transition-all ${active ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'text-gray-400 hover:bg-gray-50'}`}>{icon}{label}</button>
);
const MobileNavLink = ({ icon, active, onClick }: any) => (
  <button onClick={onClick} className={`p-3 rounded-2xl transition-all ${active ? 'text-blue-600 bg-blue-50' : 'text-gray-400'}`}>{icon}</button>
);
const StatCard = ({ title, value, trend, trendType, icon }: any) => (
  <div className="bg-white p-6 rounded-3xl border border-gray-100 flex items-start justify-between">
    <div>
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{title}</p>
      <h3 className="text-xl font-black text-gray-900 mb-1">{value}</h3>
      <div className={`text-[10px] font-bold ${trendType === 'up' ? 'text-emerald-500' : 'text-blue-500'}`}>{trend}</div>
    </div>
    <div className="p-3 bg-gray-50 rounded-xl text-gray-400">{icon}</div>
  </div>
);

const BudgetsView = ({ goals, transactions, formatMoney, lang, onAddClick, user }: any) => {
  const t = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold">{t.budgets}</h2>
        <button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{t.new_budget}</button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {goals.map((g: any) => {
          const spent = transactions.filter((tr: any) => tr.category === g.category).reduce((s: number, tr: any) => s + tr.amount, 0);
          const p = Math.min((spent / g.limit) * 100, 100);
          return (
            <div key={g.id} className="bg-white p-6 rounded-3xl border border-gray-100 relative group">
              <button onClick={() => dataService.deleteGoal(user.uid, g.id)} className="absolute top-4 right-4 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="w-4 h-4"/></button>
              <div className="flex items-center gap-3 mb-4">
                <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">{CATEGORY_ICONS[g.category as Category]}</div>
                <span className="font-bold">{(t.categories as any)[g.category]}</span>
              </div>
              <div className="w-full h-2 bg-gray-50 rounded-full overflow-hidden mb-2"><div className={`h-full ${p > 90 ? 'bg-red-500' : 'bg-blue-600'}`} style={{width: `${p}%`}}/></div>
              <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase tracking-wider">
                <span>{formatMoney(spent)} / {formatMoney(g.limit)}</span>
                <span>{p.toFixed(0)}%</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const AccountsView = ({ accounts, formatMoney, lang, onAddClick, user }: any) => {
  const t = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold">{t.accounts}</h2>
        <button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{t.new_account}</button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map((acc: any) => (
          <div key={acc.id} className="bg-gradient-to-br from-indigo-600 to-blue-700 p-6 rounded-3xl text-white shadow-lg relative group">
            <button onClick={() => dataService.deleteAccount(user.uid, acc.id)} className="absolute top-4 right-4 text-white/40 hover:text-white opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="w-4 h-4"/></button>
            <p className="text-[10px] uppercase font-bold opacity-70 mb-1">{acc.type}</p>
            <h3 className="text-lg font-bold mb-4">{acc.name}</h3>
            <p className="text-2xl font-black">{formatMoney(acc.balance)}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

const BudgetForm = ({ onAdd, onClose, lang }: any) => {
  const t = translations[lang];
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [limit, setLimit] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm">
        <h2 className="text-2xl font-black mb-6">{t.new_budget}</h2>
        <div className="space-y-4">
          <select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full border p-4 rounded-2xl bg-gray-50">{CATEGORIES.map(c => <option key={c} value={c}>{(t.categories as any)[c]}</option>)}</select>
          <input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50" placeholder="0.00" />
          <div className="flex gap-4 pt-4">
            <button onClick={onClose} className="flex-1 font-bold text-gray-500">{t.cancel}</button>
            <button onClick={() => { onAdd({ id: Math.random().toString(), category, limit: Number(limit) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{t.save}</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const AccountForm = ({ onAdd, onClose, lang }: any) => {
  const t = translations[lang];
  const [name, setName] = useState('');
  const [type, setType] = useState<AccountType>('Checking');
  const [balance, setBalance] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm">
        <h2 className="text-2xl font-black mb-6">{t.new_account}</h2>
        <div className="space-y-4">
          <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50" placeholder={t.account_name} />
          <select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border p-4 rounded-2xl bg-gray-50">
            {['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(accType => <option key={accType} value={accType}>{(t.account_types as any)[accType]}</option>)}
          </select>
          <input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50" placeholder="0.00" />
          <div className="flex gap-4 pt-4">
            <button onClick={onClose} className="flex-1 font-bold text-gray-500">{t.cancel}</button>
            <button onClick={() => { onAdd({ id: Math.random().toString(), name, type, balance: Number(balance) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{t.create}</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BehavioralInsight, BudgetGoal, Currency, Account, Category, AccountType } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import AuthScreen from './components/AuthScreen';
import { getBehavioralInsights } from './services/geminiService';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  TrendingUp, Globe, Languages, LogOut, Settings, Trash2
} from 'lucide-react';

type ViewType = 'dashboard' | 'history' | 'budgets' | 'accounts' | 'settings';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>(() => {
    const saved = localStorage.getItem('fin_lang');
    return (saved as Language) || 'en';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    const saved = localStorage.getItem('fin_currency');
    return saved ? JSON.parse(saved) : CURRENCIES[0];
  });

  const [showForm, setShowForm] = useState(false);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);

  // Firestore state
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (u) => {
      setUser(u);
      setAuthLoading(false);
    }, (error) => {
      console.error("Auth State Error:", error);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) {
      setTransactions([]);
      setGoals([]);
      setAccounts([]);
      return;
    }
    const unsubT = dataService.subscribeToUserData(user.uid, 'transactions', setTransactions);
    const unsubG = dataService.subscribeToUserData(user.uid, 'goals', setGoals);
    const unsubA = dataService.subscribeToUserData(user.uid, 'accounts', (data) => {
      if (data.length === 0) {
        const defaults: Account[] = [
          { id: 'acc1', name: 'Main Wallet', type: 'Checking', balance: 5000 },
          { id: 'acc2', name: 'Emergency Fund', type: 'Savings', balance: 12000 }
        ];
        defaults.forEach(acc => dataService.saveAccount(user.uid, acc));
      } else {
        setAccounts(data);
      }
    });
    return () => { unsubT(); unsubG(); unsubA(); };
  }, [user]);

  useEffect(() => {
    localStorage.setItem('fin_currency', JSON.stringify(currency));
    localStorage.setItem('fin_lang', lang);
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [currency, lang]);

  const refreshInsights = useCallback(async () => {
    if (transactions.length < 3) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals, lang);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals, lang]);

  useEffect(() => {
    if (user && transactions.length > 0) refreshInsights();
  }, [transactions.length, user, refreshInsights]);

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalSpent = useMemo(() => transactions.reduce((acc, curr) => acc + curr.amount, 0), [transactions]);
  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const handleLogout = async () => { await signOut(auth); };

  const addTransaction = async (entry: Transaction) => {
    if (!user) return;
    await dataService.addTransaction(user.uid, entry);
    const account = accounts.find(a => a.id === entry.accountId);
    if (account) {
      await dataService.updateAccountBalance(user.uid, account.id, account.balance - entry.amount);
