import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, BehavioralInsight, BudgetGoal } from "../types";

export const getBehavioralInsights = async (
  transactions: Transaction[],
  goals: BudgetGoal[],
  lang: 'en' | 'ar' = 'en'
): Promise<BehavioralInsight[]> => {
  // Use the API key directly from process.env.API_KEY as per guidelines.
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    console.warn("Gemini API Key is missing. Insights will be disabled.");
    return [{
      title: lang === 'ar' ? "الذكاء الاصطناعي غير مفعل" : "AI Not Configured",
      description: lang === 'ar' ? "يرجى إضافة مفتاح API الخاص بك لتفعيل التحليلات." : "Please configure your API Key to enable behavioral insights.",
      severity: "neutral",
      type: "pattern"
    }];
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze the following personal finance transactions and budget goals. 
    Provide 3 to 5 factual, neutral behavioral insights. 
    IMPORTANT: Provide the response in ${lang === 'ar' ? 'Arabic (العربية)' : 'English'}.

    Data:
    Transactions: ${JSON.stringify(transactions)}
    Budget Goals: ${JSON.stringify(goals)}

    Be precise. Provide factual patterns found in the data without being judgmental.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { 
                type: Type.STRING, 
                description: 'Values: neutral, warning, positive' 
              },
              type: { 
                type: Type.STRING, 
                description: 'Values: pattern, budget, psychology' 
              }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    const result = JSON.parse(response.text || "[]");
    return result;
  } catch (error) {
    console.error("Error fetching insights:", error);
    return [{
      title: lang === 'ar' ? "خطأ في التحليل" : "Analysis Error",
      description: lang === 'ar' ? "تعذر الاتصال بمحرك الذكاء الاصطناعي." : "Could not connect to the AI engine.",
      severity: "neutral",
      type: "pattern"
    }];
  }
};

