              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { 
                type: Type.STRING, 
                enum: ['neutral', 'warning', 'positive']
              },
              type: { 
                type: Type.STRING, 
                enum: ['pattern', 'budget', 'psychology']
              }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from Gemini");

    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini Insights Error:", error);
    return [{
      title: lang === 'ar' ? "خطأ في الاتصال" : "Connection Issue",
      description: lang === 'ar' ? "فشل تحليل البيانات حالياً." : "The AI analysis is currently unavailable.",
      severity: "neutral",
      type: "pattern"
    }];
  }
};

