import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, BehavioralInsight, BudgetGoal } from "../types";

export const getBehavioralInsights = async (
  transactions: Transaction[],
  goals: BudgetGoal[],
  lang: 'en' | 'ar' = 'en'
): Promise<BehavioralInsight[]> => {
  // Safe environment variable check to prevent ReferenceError: process is not defined
  const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : undefined;

  if (!apiKey) {
    console.warn("Gemini API Key missing or process.env is not defined.");
    return [{
      title: lang === 'ar' ? "الذكاء الاصطناعي غير مفعل" : "AI Not Connected",
      description: lang === 'ar' ? "يرجى تهيئة مفتاح API." : "Please configure the API key to see insights.",
      severity: "neutral",
      type: "pattern"
    }];
  }

  try {
    const ai = new GoogleGenAI({ apiKey });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze these 50 transactions for patterns: ${JSON.stringify(transactions.slice(0, 50))}. Language: ${lang}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { type: Type.STRING, enum: ['neutral', 'warning', 'positive'] },
              type: { type: Type.STRING, enum: ['pattern', 'budget', 'psychology'] }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Error:", error);
    return [];
  }
};

