import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, BehavioralInsight, BudgetGoal } from "../types";

export const getBehavioralInsights = async (
  transactions: Transaction[],
  goals: BudgetGoal[],
  lang: 'en' | 'ar' = 'en'
): Promise<BehavioralInsight[]> => {

  // Safe access to environment variables
  const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : undefined;

  if (!apiKey) {
    console.warn("Gemini API Key missing.");
    return [{
      title: lang === 'ar' ? "الذكاء الاصطناعي غير مفعل" : "AI Analysis Unavailable",
      description: lang === 'ar' ? "يرجى تهيئة مفتاح API." : "AI features require an API key to provide behavioral feedback.",
      severity: "neutral",
      type: "pattern"
    }];
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze these personal finance transactions and goals. 
    Provide 3-5 neutral, data-driven behavioral insights in ${lang === 'ar' ? 'Arabic' : 'English'}.
    Focus on time patterns (e.g., weekend vs weekday), mood correlations, and budget proximity.
    Data: ${JSON.stringify(transactions.slice(0, 50))} / Goals: ${JSON.stringify(goals)}
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { type: Type.STRING, enum: ['neutral', 'warning', 'positive'] },
              type: { type: Type.STRING, enum: ['pattern', 'budget', 'psychology'] }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Error:", error);
    return [];
  }
};

