import { 
  collection, 
  addDoc, 
  query, 
  onSnapshot, 
  doc, 
  deleteDoc, 
  setDoc, 
  updateDoc,
  orderBy,
  serverTimestamp 
} from "firebase/firestore";
import { db } from "../firebase";
import { Transaction, BudgetGoal, Account } from "../types";

export const dataService = {
  // Real-time subscription to any user sub-collection
  subscribe: <T>(userId: string, subCollection: string, callback: (data: T[]) => void) => {
    const q = query(collection(db, "users", userId, subCollection));
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as T[];
      callback(data);
    });
  },

  // Transactions
  addTransaction: async (userId: string, transaction: Omit<Transaction, 'id'>) => {
    return addDoc(collection(db, "users", userId, "transactions"), {
      ...transaction,
      createdAt: serverTimestamp()
    });
  },

  deleteTransaction: async (userId: string, transactionId: string) => {
    return deleteDoc(doc(db, "users", userId, "transactions", transactionId));
  },

  // Goals
  saveGoal: async (userId: string, goal: BudgetGoal) => {
    const { id, ...data } = goal;
    const docRef = id && id.length > 15 ? doc(db, "users", userId, "goals", id) : doc(collection(db, "users", userId, "goals"));
    return setDoc(docRef, data, { merge: true });
  },

  deleteGoal: async (userId: string, goalId: string) => {
    return deleteDoc(doc(db, "users", userId, "goals", goalId));
  },

  // Accounts
  saveAccount: async (userId: string, account: Account) => {
    const { id, ...data } = account;
    const docRef = id && id.length > 15 ? doc(db, "users", userId, "accounts", id) : doc(collection(db, "users", userId, "accounts"));
    return setDoc(docRef, data, { merge: true });
  },

  updateAccountBalance: async (userId: string, accountId: string, newBalance: number) => {
    return updateDoc(doc(db, "users", userId, "accounts", accountId), { balance: newBalance });
  },

  deleteAccount: async (userId: string, accountId: string) => {
    return deleteDoc(doc(db, "users", userId, "accounts", accountId));
  }
};

