export default App;

export type Category = 
  | 'Food & Dining'
  | 'Transportation'
  | 'Shopping'
  | 'Entertainment'
  | 'Bills & Utilities'
  | 'Health'
  | 'Education'
  | 'Other';

export type Mood = 'Happy' | 'Stressed' | 'Tired' | 'Bored' | 'Excited' | 'Neutral';

export type Currency = {
  code: string;
  symbol: string;
  label: string;
};

export type AccountType = 'Checking' | 'Savings' | 'Credit Card' | 'Investment' | 'Cash';

export interface UserSettings {
  language: 'en' | 'ar';
  currency: Currency;
  updatedAt?: any; // Firestore Timestamp
}

export interface Account {
  id: string;
  userId: string;
  name: string;
  type: AccountType;
  balance: number;
  createdAt?: any;
}

export interface Transaction {
  id: string;
  userId: string;
  amount: number;
  category: Category;
  date: string; 
  time: string; 
  description: string;
  mood: Mood;
  accountId: string;
  createdAt?: any;
}

export interface BehavioralInsight {
  title: string;
  description: string;
  severity: 'neutral' | 'warning' | 'positive';
  type: 'pattern' | 'budget' | 'psychology';
}

export interface BudgetGoal {
  id: string;
  userId: string;
  category: Category;
  limit: number;
  createdAt?: any;
}

import { 
  collection, 
  addDoc, 
  query, 
  onSnapshot, 
  doc, 
  deleteDoc, 
  setDoc, 
  updateDoc,
  serverTimestamp 
} from "firebase/firestore";
import { db } from "../firebase";
import { Transaction, BudgetGoal, Account, UserSettings } from "../types";

export const dataService = {
  // Settings
  subscribeToSettings: (userId: string, callback: (settings: UserSettings | null) => void) => {
    return onSnapshot(doc(db, "users", userId, "config", "preferences"), (doc) => {
      if (doc.exists()) {
        callback(doc.data() as UserSettings);
      } else {
        callback(null);
      }
    });
  },

  saveSettings: async (userId: string, settings: UserSettings) => {
    return setDoc(doc(db, "users", userId, "config", "preferences"), {
      ...settings,
      updatedAt: serverTimestamp()
    });
  },

  // Generic Subscription
  subscribe: <T>(userId: string, subCollection: string, callback: (data: T[]) => void) => {
    const q = query(collection(db, "users", userId, subCollection));
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as T[];
      callback(data);
    });
  },

  // Transactions
  addTransaction: async (userId: string, transaction: Omit<Transaction, 'id' | 'userId'>) => {
    return addDoc(collection(db, "users", userId, "transactions"), {
      ...transaction,
      userId,
      createdAt: serverTimestamp()
    });
  },

  deleteTransaction: async (userId: string, transactionId: string) => {
    return deleteDoc(doc(db, "users", userId, "transactions", transactionId));
  },

  // Goals
  saveGoal: async (userId: string, goal: Omit<BudgetGoal, 'id' | 'userId'> & { id?: string }) => {
    const { id, ...data } = goal;
    const docRef = id && id.length > 15 ? doc(db, "users", userId, "goals", id) : doc(collection(db, "users", userId, "goals"));
    return setDoc(docRef, { ...data, userId, createdAt: serverTimestamp() }, { merge: true });
  },

  deleteGoal: async (userId: string, goalId: string) => {
    return deleteDoc(doc(db, "users", userId, "goals", goalId));
  },

  // Accounts
  saveAccount: async (userId: string, account: Omit<Account, 'id' | 'userId'> & { id?: string }) => {
    const { id, ...data } = account;
    const docRef = id && id.length > 15 ? doc(db, "users", userId, "accounts", id) : doc(collection(db, "users", userId, "accounts"));
    return setDoc(docRef, { ...data, userId, createdAt: serverTimestamp() }, { merge: true });
  },

  updateAccountBalance: async (userId: string, accountId: string, newBalance: number) => {
    return updateDoc(doc(db, "users", userId, "accounts", accountId), { balance: newBalance });
  },

  deleteAccount: async (userId: string, accountId: string) => {
    return deleteDoc(doc(db, "users", userId, "accounts", accountId));
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BehavioralInsight, BudgetGoal, Currency, Account, Category, AccountType, UserSettings } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import AuthScreen from './components/AuthScreen';
import { getBehavioralInsights } from './services/geminiService';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  Search, TrendingUp, X, Trash2, Globe, Languages, LogOut, Loader2
} from 'lucide-react';

type ViewType = 'dashboard' | 'history' | 'budgets' | 'accounts';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>('en');
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);

  const [showForm, setShowForm] = useState(false);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);

  // Auth & Settings Sync
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (u) => {
      setUser(u);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    // Sync Preferences from Cloud
    const unsubSettings = dataService.subscribeToSettings(user.uid, (settings) => {
      if (settings) {
        setLang(settings.language);
        setCurrency(settings.currency);
      } else {
        // First time user, save current defaults to cloud
        dataService.saveSettings(user.uid, { language: lang, currency });
      }
    });

    const unsubT = dataService.subscribe(user.uid, 'transactions', (data: Transaction[]) => {
      setTransactions(data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    });

    const unsubG = dataService.subscribe(user.uid, 'goals', (data: BudgetGoal[]) => {
      setGoals(data.length > 0 ? data : INITIAL_GOALS.map(g => ({ ...g, userId: user.uid })));
    });

    const unsubA = dataService.subscribe(user.uid, 'accounts', (data: Account[]) => {
      if (data.length === 0) {
        const defaults = [
          { name: 'Main Wallet', type: 'Checking' as AccountType, balance: 5000 },
          { name: 'Savings', type: 'Savings' as AccountType, balance: 10000 }
        ];
        defaults.forEach(acc => dataService.saveAccount(user.uid, acc));
      } else {
        setAccounts(data);
      }
    });

    return () => {
      unsubSettings();
      unsubT();
      unsubG();
      unsubA();
    };
  }, [user]);

  // Update UI direction and local storage for fast initial loads
  useEffect(() => {
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
    localStorage.setItem('fin_lang', lang);
    localStorage.setItem('fin_currency', JSON.stringify(currency));
  }, [lang, currency]);

  const updateLanguage = (newLang: Language) => {
    setLang(newLang);
    if (user) dataService.saveSettings(user.uid, { language: newLang, currency });
  };

  const updateCurrency = (newCurrency: Currency) => {
    setCurrency(newCurrency);
    if (user) dataService.saveSettings(user.uid, { language: lang, currency: newCurrency });
  };

  const refreshInsights = useCallback(async () => {
    if (transactions.length < 3) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals, lang);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals, lang]);

  useEffect(() => {
    if (user && transactions.length > 0) refreshInsights();
  }, [transactions.length, user, refreshInsights]);

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalSpent = useMemo(() => transactions.reduce((acc, curr) => acc + curr.amount, 0), [transactions]);
  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  if (authLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#f8fafc]">
        <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
        <p className="text-gray-400 font-bold uppercase tracking-widest text-[10px]">Cloud Syncing...</p>
      </div>
    );
  }

  if (!user) {
    return <AuthScreen lang={lang} onLanguageToggle={() => updateLanguage(lang === 'en' ? 'ar' : 'en')} />;
  }

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-[#f8fafc]" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      {/* Desktop Sidebar */}
      <nav className={`fixed ${lang === 'ar' ? 'right-0' : 'left-0'} top-0 h-full w-64 bg-white border-${lang === 'ar' ? 'l' : 'r'} border-gray-100 p-6 hidden lg:flex flex-col z-30`}>
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-black bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-700 tracking-tight">FinSense AI</span>
        </div>
        <div className="space-y-2">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label={t.overview} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label={t.history} active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label={t.budgets} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label={t.accounts} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
        </div>

        <div className="mt-auto space-y-4">
           <button onClick={() => signOut(auth)} className="w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold text-rose-500 hover:bg-rose-50 transition-all mb-4">
             <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'خروج' : 'Logout'}
           </button>

           <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100">
             <div className="flex items-center gap-2 mb-3 text-blue-600">
                <Languages className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.language}</span>
             </div>
             <div className="flex gap-1 bg-white p-1 rounded-xl shadow-sm">
                <button onClick={() => updateLanguage('en')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'en' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>EN</button>
                <button onClick={() => updateLanguage('ar')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'ar' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>AR</button>
             </div>
           </div>

           <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
             <div className="flex items-center gap-2 mb-3 text-gray-500">
                <Globe className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.currency}</span>
             </div>
             <select 
               value={JSON.stringify(currency)} 
               onChange={(e) => updateCurrency(JSON.parse(e.target.value))}
               className="bg-white border border-gray-100 text-xs font-bold text-gray-700 outline-none w-full p-2.5 rounded-xl shadow-sm"
             >
               {CURRENCIES.map(c => <option key={c.code} value={JSON.stringify(c)}>{c.label} ({c.symbol})</option>)}
             </select>
           </div>
        </div>
      </nav>

      <main className={`${lang === 'ar' ? 'lg:mr-64' : 'lg:ml-64'} p-4 lg:p-10 max-w-7xl mx-auto min-h-screen`}>
        <header className="flex justify-between items-center mb-10">
          <div>
            <h1 className="text-3xl font-black text-gray-900 capitalize tracking-tight">{(t as any)[activeView]}</h1>
            <p className="text-sm font-medium text-gray-400 mt-1">
              {t.currency}: <span className="text-blue-600 font-bold">{currency.code}</span> • {user.email}
            </p>
          </div>
          <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-bold shadow-xl shadow-blue-100 active:scale-95 transition-all text-sm">
             <Plus className="w-5 h-5" /> <span className="hidden sm:inline">{t.entry}</span>
          </button>
        </header>

        {activeView === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              <StatCard title={t.total_expenses} value={formatMoney(totalSpent)} trend={t.trend_monthly} trendType="down" icon={<Wallet className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.total_assets} value={formatMoney(totalBalance)} trend={t.trend_liquid} trendType="up" icon={<TrendingUp className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.budget_health} value={`${goals.length}`} trend={t.trend_goals} trendType="up" icon={<Target className="w-5 h-5" />} lang={lang} />
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
              <div className="xl:col-span-2 space-y-8"><Charts transactions={transactions} /></div>
              <div className="xl:col-span-1"><AIInsights insights={insights} loading={loadingInsights} onRefresh={refreshInsights} lang={lang} /></div>
            </div>
          </div>
        )}
        {activeView === 'history' && <TransactionList transactions={transactions} onDelete={(id) => dataService.deleteTransaction(user.uid, id)} lang={lang} />}
        {activeView === 'budgets' && <BudgetsView user={user} goals={goals} transactions={transactions} formatMoney={formatMoney} lang={lang} onAddClick={() => setShowBudgetForm(true)} />}
        {activeView === 'accounts' && <AccountsView user={user} accounts={accounts} formatMoney={formatMoney} lang={lang} onAddClick={() => setShowAccountForm(true)} />}
      </main>

      {/* Mobile Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-gray-100 px-6 py-3 flex justify-around items-center lg:hidden z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] rounded-t-[2.5rem]">
        <MobileNavLink icon={<LayoutDashboard className="w-6 h-6" />} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
        <MobileNavLink icon={<History className="w-6 h-6" />} active={activeView === 'history'} onClick={() => setActiveView('history')} />
        <button onClick={() => setShowForm(true)} className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center -translate-y-6 active:scale-90 transition-transform"><Plus className="w-7 h-7" /></button>
        <MobileNavLink icon={<Target className="w-6 h-6" />} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
        <MobileNavLink icon={<CreditCard className="w-6 h-6" />} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
      </nav>

      {showForm && <TransactionForm accounts={accounts} onAdd={(t) => dataService.addTransaction(user.uid, t)} onClose={() => setShowForm(false)} lang={lang} />}
      {showBudgetForm && <BudgetForm onAdd={(b: any) => dataService.saveGoal(user.uid, b)} onClose={() => setShowBudgetForm(false)} lang={lang} />}
      {showAccountForm && <AccountForm onAdd={(a: any) => dataService.saveAccount(user.uid, a)} onClose={() => setShowAccountForm(false)} lang={lang} />}
    </div>
  );
};

// Internal UI Components
const NavLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold transition-all ${active ? 'bg-blue-50 text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:bg-gray-50'}`}>{icon}{label}</button>
);
const MobileNavLink = ({ icon, active, onClick }: any) => (
  <button onClick={onClick} className={`p-3 rounded-2xl transition-all ${active ? 'text-blue-600 bg-blue-50 shadow-sm' : 'text-gray-400'}`}>{icon}</button>
);
const StatCard = ({ title, value, trend, trendType, icon }: any) => (
  <div className="bg-white p-7 rounded-[2rem] border border-gray-100 flex items-start justify-between shadow-sm">
    <div>
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">{title}</p>
      <h3 className="text-2xl font-black text-gray-900 mb-2">{value}</h3>
      <div className={`text-[10px] font-bold ${trendType === 'up' ? 'text-emerald-500' : 'text-blue-500'}`}>{trend}</div>
    </div>
    <div className="p-4 bg-gray-50 rounded-2xl text-gray-400">{icon}</div>
  </div>
);

const BudgetsView = ({ goals, transactions, formatMoney, lang, onAddClick, user }: any) => {
  const tStrings = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStrings.budgets}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStrings.new_budget}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {goals.map((goal: any) => {
          const spent = transactions.filter((tr: any) => tr.category === goal.category).reduce((s: number, tr: any) => s + tr.amount, 0);
          const percent = Math.min((spent / goal.limit) * 100, 100);
          return (
            <div key={goal.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm"><div className="flex justify-between mb-4"><div className="flex items-center gap-3"><div className="p-2.5 bg-blue-50 text-blue-600 rounded-xl">{CATEGORY_ICONS[goal.category as Category]}</div><h3 className="font-bold">{(tStrings.categories as any)[goal.category]}</h3></div><button onClick={() => dataService.deleteGoal(user.uid, goal.id)} className="text-gray-300 hover:text-red-500"><Trash2 className="w-4 h-4" /></button></div><div className="w-full h-2 bg-gray-50 rounded-full overflow-hidden mb-2"><div className={`h-full ${percent > 90 ? 'bg-red-500' : 'bg-blue-600'}`} style={{width: `${percent}%`}} /></div><div className="flex justify-between text-[10px] font-bold text-gray-400 uppercase"><span>{formatMoney(spent)} / {formatMoney(goal.limit)}</span><span>{percent.toFixed(0)}%</span></div></div>
          );
        })}
      </div>
    </div>
  );
};

const AccountsView = ({ accounts, formatMoney, lang, onAddClick, user }: any) => {
  const tStrings = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStrings.accounts}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStrings.new_account}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map((acc: any) => (
          <div key={acc.id} className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-[2.5rem] text-white shadow-xl relative group"><button onClick={() => dataService.deleteAccount(user.uid, acc.id)} className="absolute top-6 right-6 text-white/40 hover:text-white"><Trash2 className="w-4 h-4" /></button><p className="text-[10px] uppercase font-bold opacity-70 mb-1">{(tStrings.account_types as any)[acc.type]}</p><h3 className="text-xl font-bold mb-6">{acc.name}</h3><p className="text-3xl font-black">{formatMoney(acc.balance)}</p></div>
        ))}
      </div>
    </div>
  );
};

const BudgetForm = ({ onAdd, onClose, lang }: any) => {
  const tStrings = translations[lang];
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [limit, setLimit] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4"><div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm"><h2 className="text-2xl font-black mb-6">{tStrings.new_budget}</h2><div className="space-y-4"><select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none">{CATEGORIES.map(c => <option key={c} value={c}>{(tStrings.categories as any)[c]}</option>)}</select><input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none" placeholder="0.00" /><div className="flex gap-4 pt-4"><button onClick={onClose} className="flex-1 font-bold text-gray-500">{tStrings.cancel}</button><button onClick={() => { onAdd({ category, limit: Number(limit) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{tStrings.save}</button></div></div></div></div>
  );
};

const AccountForm = ({ onAdd, onClose, lang }: any) => {
  const tStrings = translations[lang];
  const [name, setName] = useState('');
  const [type, setType] = useState<AccountType>('Checking');
  const [balance, setBalance] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4"><div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm"><h2 className="text-2xl font-black mb-6">{tStrings.new_account}</h2><div className="space-y-4"><input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none" placeholder={tStrings.account_name} /><select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none">{['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(accType => <option key={accType} value={accType}>{(tStrings.account_types as any)[accType]}</option>)}</select><input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none" placeholder="0.00" /><div className="flex gap-4 pt-4"><button onClick={onClose} className="flex-1 font-bold text-gray-500">{tStrings.cancel}</button><button onClick={() => { onAdd({ name, type, balance: Number(balance) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{tStrings.create}</button></div></div></div></div>
  );
};

export default App;

