import React, { useState } from 'react';
import { CATEGORIES, MOODS } from '../constants';
import { Transaction, Category, Mood, Account } from '../types';
import { PlusCircle, X, CreditCard } from 'lucide-react';
import { Language, translations } from '../translations';

interface Props {
  accounts: Account[];
  // Fixed: Changed onAdd parameter type to Omit<Transaction, 'userId'> because the userId is added at the service layer
  onAdd: (t: Omit<Transaction, 'userId'>) => void;
  onClose: () => void;
  lang: Language;
}

const TransactionForm: React.FC<Props> = ({ accounts, onAdd, onClose, lang }) => {
  const t = translations[lang];
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
