import { 
  collection, 
  addDoc, 
  query, 
  onSnapshot, 
  doc, 
  deleteDoc, 
  setDoc, 
  updateDoc,
  getDoc,
  serverTimestamp 
} from "firebase/firestore";
import { db } from "../firebase";
import { Transaction, BudgetGoal, Account, UserSettings } from "../types";

export const dataService = {
  // User Management
  ensureUserProfile: async (userId: string, email: string) => {
    const userDocRef = doc(db, "users", userId);
    const userDoc = await getDoc(userDocRef);

    if (!userDoc.exists()) {
      // Create the base user document seen in your screenshot
      await setDoc(userDocRef, {
        email: email,
        name: email.split('@')[0],
        createdAt: serverTimestamp()
      });
    }
  },

  // Settings
  subscribeToSettings: (userId: string, callback: (settings: UserSettings | null) => void) => {
    return onSnapshot(doc(db, "users", userId, "config", "preferences"), (doc) => {
      if (doc.exists()) {
        callback(doc.data() as UserSettings);
      } else {
        callback(null);
      }
    });
  },

  saveSettings: async (userId: string, settings: UserSettings) => {
    return setDoc(doc(db, "users", userId, "config", "preferences"), {
      ...settings,
      updatedAt: serverTimestamp()
    });
  },

  // Generic Subscription
  subscribe: <T>(userId: string, subCollection: string, callback: (data: T[]) => void) => {
    const q = query(collection(db, "users", userId, subCollection));
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as T[];
      callback(data);
    });
  },

  // Transactions
  addTransaction: async (userId: string, transaction: Omit<Transaction, 'id' | 'userId'>) => {
    return addDoc(collection(db, "users", userId, "transactions"), {
      ...transaction,
      userId,
      createdAt: serverTimestamp()
    });
  },

  deleteTransaction: async (userId: string, transactionId: string) => {
    return deleteDoc(doc(db, "users", userId, "transactions", transactionId));
  },

  // Goals
  saveGoal: async (userId: string, goal: Omit<BudgetGoal, 'id' | 'userId'> & { id?: string }) => {
    const { id, ...data } = goal;
    // If id exists and isn't just a template '1', '2', '3', use it. Otherwise let Firestore auto-gen.
    const isTemplateId = id === '1' || id === '2' || id === '3';
    const docRef = (id && !isTemplateId) 
      ? doc(db, "users", userId, "goals", id) 
      : doc(collection(db, "users", userId, "goals"));

    return setDoc(docRef, { ...data, userId, updatedAt: serverTimestamp() }, { merge: true });
  },

  deleteGoal: async (userId: string, goalId: string) => {
    return deleteDoc(doc(db, "users", userId, "goals", goalId));
  },

  // Accounts
  saveAccount: async (userId: string, account: Omit<Account, 'id' | 'userId'> & { id?: string }) => {
    const { id, ...data } = account;
    const isInitialId = id?.startsWith('initial');
    const docRef = (id && !isInitialId) 
      ? doc(db, "users", userId, "accounts", id) 
      : doc(collection(db, "users", userId, "accounts"));

    return setDoc(docRef, { ...data, userId, updatedAt: serverTimestamp() }, { merge: true });
  },

  updateAccountBalance: async (userId: string, accountId: string, newBalance: number) => {
    return updateDoc(doc(db, "users", userId, "accounts", accountId), { balance: newBalance });
  },

  deleteAccount: async (userId: string, accountId: string) => {
    return deleteDoc(doc(db, "users", userId, "accounts", accountId));
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
