);
const StatCard = ({ title, value, trend, trendType, icon }: any) => (
  <div className="bg-white p-7 rounded-[2rem] border border-gray-100 flex items-start justify-between shadow-sm">
    <div>
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">{title}</p>
      <h3 className="text-2xl font-black text-gray-900 mb-2">{value}</h3>
      <div className={`text-[10px] font-bold ${trendType === 'up' ? 'text-emerald-500' : 'text-blue-500'}`}>{trend}</div>
    </div>
    <div className="p-4 bg-gray-50 rounded-2xl text-gray-400">{icon}</div>
  </div>
);

const BudgetsView = ({ goals, transactions, formatMoney, lang, onAddClick, user }: any) => {
