  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStr.budgets}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStr.new_budget}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {goals.map((goal: any) => {
          const spent = transactions.filter((tr: any) => tr.category === goal.category).reduce((s: number, tr: any) => s + tr.amount, 0);
          const percent = Math.min((spent / goal.limit) * 100, 100);
          return (
            <div key={goal.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm group">
              <div className="flex justify-between mb-4">
                <div className="flex items-center gap-3">
                   <div className="p-2.5 bg-blue-50 text-blue-600 rounded-xl">{CATEGORY_ICONS[goal.category as Category]}</div>
                   <h3 className="font-bold">{(tStr.categories as any)[goal.category]}</h3>
                </div>
                <button onClick={() => dataService.deleteGoal(user.uid, goal.id)} className="text-gray-300 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
              </div>
              <div className="w-full h-2 bg-gray-50 rounded-full overflow-hidden mb-2"><div className={`h-full ${percent > 90 ? 'bg-red-500' : 'bg-blue-600'}`} style={{width: `${percent}%`}} /></div>
              <div className="flex justify-between text-[10px] font-bold text-gray-400 uppercase"><span>{formatMoney(spent)} / {formatMoney(goal.limit)}</span><span>{percent.toFixed(0)}%</span></div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const AccountsView = ({ accounts, formatMoney, lang, onAddClick, user }: any) => {
  const tStr = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStr.accounts}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStr.new_account}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map((acc: any) => (
          <div key={acc.id} className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-[2.5rem] text-white shadow-xl relative group">
            <button onClick={() => dataService.deleteAccount(user.uid, acc.id)} className="absolute top-6 right-6 text-white/40 hover:text-white"><Trash2 className="w-4 h-4" /></button>
            <p className="text-[10px] uppercase font-bold opacity-70 mb-1">{(tStr.account_types as any)[acc.type]}</p>
            <h3 className="text-xl font-bold mb-6">{acc.name}</h3>
            <p className="text-3xl font-black">{formatMoney(acc.balance)}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

const BudgetForm = ({ onAdd, onClose, lang }: any) => {
