  const [name, setName] = useState('');
  const [type, setType] = useState<AccountType>('Checking');
  const [balance, setBalance] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4"><div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm"><h2 className="text-2xl font-black mb-6">{tStr.new_account}</h2><div className="space-y-4"><input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold" placeholder={tStr.account_name} /><select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold">{['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(at => <option key={at} value={at}>{(tStr.account_types as any)[at]}</option>)}</select><input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold" placeholder="0.00" /><div className="flex gap-4 pt-4"><button onClick={onClose} className="flex-1 font-bold text-gray-500">{tStr.cancel}</button><button onClick={() => { onAdd({ name, type, balance: Number(balance) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{tStr.create}</button></div></div></div></div>
  );
