};

const AccountsView = ({ accounts, formatMoney, lang, onAddClick, user }: any) => {
  const tStr = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStr.accounts}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStr.new_account}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map((acc: any) => (
          <div key={acc.id} className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-[2.5rem] text-white shadow-xl relative group">
            {/* Trash2 component is now available via import */}
            <button onClick={() => dataService.deleteAccount(user.uid, acc.id)} className="absolute top-6 right-6 text-white/40 hover:text-white"><Trash2 className="w-4 h-4" /></button>
            <p className="text-[10px] uppercase font-bold opacity-70 mb-1">{(tStr.account_types as any)[acc.type]}</p>
            <h3 className="text-xl font-bold mb-6">{acc.name}</h3>
            <p className="text-3xl font-black">{formatMoney(acc.balance)}</p>
          </div>
        ))}
      </div>
    </div>
