};

const BudgetForm = ({ onAdd, onClose, lang }: any) => {
  const tStr = translations[lang];
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [limit, setLimit] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4"><div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm"><h2 className="text-2xl font-black mb-6">{tStr.new_budget}</h2><div className="space-y-4"><select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none">{CATEGORIES.map(c => <option key={c} value={c}>{(tStr.categories as any)[c]}</option>)}</select><input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold" placeholder="0.00" /><div className="flex gap-4 pt-4"><button onClick={onClose} className="flex-1 font-bold text-gray-500">{tStr.cancel}</button><button onClick={() => { onAdd({ category, limit: Number(limit) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{tStr.save}</button></div></div></div></div>
  );
};

const AccountForm = ({ onAdd, onClose, lang }: any) => {
  const tStr = translations[lang];
  const [name, setName] = useState('');
  const [type, setType] = useState<AccountType>('Checking');
  const [balance, setBalance] = useState('');
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[60] p-4"><div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm"><h2 className="text-2xl font-black mb-6">{tStr.new_account}</h2><div className="space-y-4"><input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold" placeholder={tStr.account_name} /><select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold">{['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(at => <option key={at} value={at}>{(tStr.account_types as any)[at]}</option>)}</select><input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold" placeholder="0.00" /><div className="flex gap-4 pt-4"><button onClick={onClose} className="flex-1 font-bold text-gray-500">{tStr.cancel}</button><button onClick={() => { onAdd({ name, type, balance: Number(balance) }); onClose(); }} className="flex-1 bg-blue-600 text-white p-4 rounded-2xl font-bold">{tStr.create}</button></div></div></div></div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BehavioralInsight, BudgetGoal, Currency, Account, Category, AccountType, UserSettings } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import AuthScreen from './components/AuthScreen';
import { getBehavioralInsights } from './services/geminiService';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  TrendingUp, Languages, LogOut, Loader2, Globe, Trash2, Settings, X, Calendar
} from 'lucide-react';

type ViewType = 'dashboard' | 'history' | 'budgets' | 'accounts';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>('en');
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showForm, setShowForm] = useState(false);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);

  // Live clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (u) => {
      if (u) {
        await dataService.ensureUserProfile(u.uid, u.email || '');
      }
      setUser(u);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Data Sync
  useEffect(() => {
    if (!user) return;

    const unsubSettings = dataService.subscribeToSettings(user.uid, (settings) => {
      if (settings) {
        setLang(settings.language);
        setCurrency(settings.currency);
      } else {
        dataService.saveSettings(user.uid, { language: lang, currency });
      }
    });

    const unsubT = dataService.subscribe(user.uid, 'transactions', (data: Transaction[]) => {
      setTransactions(data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    });

    const unsubG = dataService.subscribe(user.uid, 'goals', (data: BudgetGoal[]) => {
      if (data.length === 0) {
        INITIAL_GOALS.forEach(g => dataService.saveGoal(user.uid, g));
      } else {
        setGoals(data);
      }
    });

    const unsubA = dataService.subscribe(user.uid, 'accounts', (data: Account[]) => {
      if (data.length === 0) {
        const defaults = [
          { name: 'Cash Wallet', type: 'Cash' as AccountType, balance: 1000 },
          { name: 'Primary Bank', type: 'Checking' as AccountType, balance: 5000 }
        ];
        defaults.forEach(acc => dataService.saveAccount(user.uid, acc));
      } else {
        setAccounts(data);
      }
    });

    return () => {
      unsubSettings();
      unsubT();
      unsubG();
      unsubA();
    };
  }, [user]);

  useEffect(() => {
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [lang]);

  const updateLanguage = (newLang: Language) => {
    setLang(newLang);
    if (user) dataService.saveSettings(user.uid, { language: newLang, currency });
  };

  const updateCurrencyByCode = (code: string) => {
    const selected = CURRENCIES.find(c => c.code === code);
    if (selected) {
      setCurrency(selected);
      if (user) dataService.saveSettings(user.uid, { language: lang, currency: selected });
    }
  };

  const refreshInsights = useCallback(async () => {
    if (transactions.length < 3) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals, lang);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals, lang]);

  useEffect(() => {
    if (user && transactions.length > 0) refreshInsights();
  }, [transactions.length, user, refreshInsights]);

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalSpent = useMemo(() => transactions.reduce((acc, curr) => acc + curr.amount, 0), [transactions]);
  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  if (authLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#f8fafc]">
        <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
        <p className="text-gray-400 font-bold uppercase tracking-widest text-[10px]">Verifying Identity...</p>
      </div>
    );
  }

  if (!user) {
    return <AuthScreen lang={lang} onLanguageToggle={() => updateLanguage(lang === 'en' ? 'ar' : 'en')} />;
  }

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-[#f8fafc]" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      {/* Desktop Sidebar */}
      <nav className={`fixed ${lang === 'ar' ? 'right-0' : 'left-0'} top-0 h-full w-64 bg-white border-${lang === 'ar' ? 'l' : 'r'} border-gray-100 p-6 hidden lg:flex flex-col z-30`}>
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-black bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-700 tracking-tight">FinSense AI</span>
        </div>
        <div className="space-y-2">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label={t.overview} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label={t.history} active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label={t.budgets} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label={t.accounts} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
        </div>

        <div className="mt-auto space-y-4">
           <button onClick={() => signOut(auth)} className="w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold text-rose-500 hover:bg-rose-50 transition-all mb-4">
             <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'خروج' : 'Logout'}
           </button>

           <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100">
             <div className="flex items-center gap-2 mb-3 text-blue-600">
                <Languages className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.language}</span>
             </div>
             <div className="flex gap-1 bg-white p-1 rounded-xl shadow-sm">
                <button onClick={() => updateLanguage('en')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'en' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>EN</button>
                <button onClick={() => updateLanguage('ar')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'ar' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>AR</button>
             </div>
           </div>

           <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
             <div className="flex items-center gap-2 mb-3 text-gray-500">
                <Globe className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.currency}</span>
             </div>
             <select 
               value={currency.code} 
               onChange={(e) => updateCurrencyByCode(e.target.value)}
               className="bg-white border border-gray-100 text-xs font-bold text-gray-700 outline-none w-full p-2.5 rounded-xl shadow-sm cursor-pointer"
             >
               {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label} ({c.symbol})</option>)}
             </select>
           </div>
        </div>
      </nav>

      <main className={`${lang === 'ar' ? 'lg:mr-64' : 'lg:ml-64'} p-4 lg:p-10 max-w-7xl mx-auto min-h-screen`}>
        <header className="flex justify-between items-start mb-10">
          <div>
            <h1 className="text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
              {activeView === 'dashboard' ? `${t.welcome_back}, ${user.displayName || user.email?.split('@')[0]}` : (t as any)[activeView]}
            </h1>
            <div className="flex items-center gap-3 mt-1.5 text-xs font-semibold text-gray-400">
              <span className="flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5" />
                {currentTime.toLocaleDateString(lang, { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
              <span>•</span>
              <span className="text-blue-600 font-bold">{currency.code}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setShowSettingsModal(true)} className="lg:hidden p-3 bg-white border border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 transition-colors shadow-sm">
                <Settings className="w-5 h-5" />
             </button>
             <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 lg:px-6 py-3 rounded-2xl font-bold shadow-xl shadow-blue-100 active:scale-95 transition-all text-sm">
               <Plus className="w-5 h-5" /> <span className="hidden sm:inline">{t.entry}</span>
             </button>
          </div>
        </header>

        {activeView === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              <StatCard title={t.total_expenses} value={formatMoney(totalSpent)} trend={t.trend_monthly} trendType="down" icon={<Wallet className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.total_assets} value={formatMoney(totalBalance)} trend={t.trend_liquid} trendType="up" icon={<TrendingUp className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.budget_health} value={`${goals.length}`} trend={t.trend_goals} trendType="up" icon={<Target className="w-5 h-5" />} lang={lang} />
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
              <div className="xl:col-span-2 space-y-8"><Charts transactions={transactions} /></div>
              <div className="xl:col-span-1"><AIInsights insights={insights} loading={loadingInsights} onRefresh={refreshInsights} lang={lang} /></div>
            </div>
          </div>
        )}
        {activeView === 'history' && <TransactionList transactions={transactions} onDelete={(id) => dataService.deleteTransaction(user.uid, id)} lang={lang} />}
        {activeView === 'budgets' && <BudgetsView user={user} goals={goals} transactions={transactions} formatMoney={formatMoney} lang={lang} onAddClick={() => setShowBudgetForm(true)} />}
        {activeView === 'accounts' && <AccountsView user={user} accounts={accounts} formatMoney={formatMoney} lang={lang} onAddClick={() => setShowAccountForm(true)} />}
      </main>

      {/* Mobile Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-md border-t border-gray-100 px-6 py-3 flex justify-around items-center lg:hidden z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] rounded-t-[2.5rem]">
        <MobileNavLink icon={<LayoutDashboard className="w-6 h-6" />} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
        <MobileNavLink icon={<History className="w-6 h-6" />} active={activeView === 'history'} onClick={() => setActiveView('history')} />
        <button onClick={() => setShowForm(true)} className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center -translate-y-6 active:scale-90 transition-transform"><Plus className="w-7 h-7" /></button>
        <MobileNavLink icon={<Target className="w-6 h-6" />} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
        <MobileNavLink icon={<CreditCard className="w-6 h-6" />} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
      </nav>

      {/* Mobile Settings Modal */}
      {showSettingsModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-end lg:hidden animate-in fade-in duration-200" onClick={() => setShowSettingsModal(false)}>
           <div className="bg-white w-full rounded-t-[2.5rem] p-8 animate-in slide-in-from-bottom duration-300" onClick={e => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-8">
                 <h2 className="text-xl font-black text-gray-900">{t.settings}</h2>
                 <button onClick={() => setShowSettingsModal(false)} className="p-2 bg-gray-50 rounded-full"><X className="w-5 h-5 text-gray-400" /></button>
              </div>

              <div className="space-y-6">
                 <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-3">{t.language}</label>
                    <div className="flex gap-2">
                       <button onClick={() => updateLanguage('en')} className={`flex-1 py-4 rounded-2xl text-sm font-bold border transition-all ${lang === 'en' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}>English</button>
                       <button onClick={() => updateLanguage('ar')} className={`flex-1 py-4 rounded-2xl text-sm font-bold border transition-all ${lang === 'ar' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}>العربية</button>
                    </div>
                 </div>

                 <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-3">{t.currency}</label>
                    <select 
                       value={currency.code} 
                       onChange={(e) => updateCurrencyByCode(e.target.value)}
                       className="w-full py-4 px-5 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold text-gray-900 outline-none"
                    >
                       {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label} ({c.symbol})</option>)}
                    </select>
                 </div>

                 <button onClick={() => signOut(auth)} className="w-full flex items-center justify-center gap-3 py-4 text-rose-500 font-bold bg-rose-50 rounded-2xl mt-4">
                    <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'تسجيل الخروج' : 'Sign Out'}
                 </button>
              </div>
           </div>
        </div>
      )}

      {showForm && <TransactionForm accounts={accounts} onAdd={(t) => dataService.addTransaction(user.uid, t)} onClose={() => setShowForm(false)} lang={lang} />}
      {showBudgetForm && <BudgetForm onAdd={(b: any) => dataService.saveGoal(user.uid, b)} onClose={() => setShowBudgetForm(false)} lang={lang} />}
      {showAccountForm && <AccountForm onAdd={(a: any) => dataService.saveAccount(user.uid, a)} onClose={() => setShowAccountForm(false)} lang={lang} />}
    </div>
  );
};

// UI Parts
const NavLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold transition-all ${active ? 'bg-blue-50 text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:bg-gray-50'}`}>{icon}{label}</button>
);
const MobileNavLink = ({ icon, active, onClick }: any) => (
  <button onClick={onClick} className={`p-3 rounded-2xl transition-all ${active ? 'text-blue-600 bg-blue-50 shadow-sm' : 'text-gray-400'}`}>{icon}</button>
);
const StatCard = ({ title, value, trend, trendType, icon }: any) => (
  <div className="bg-white p-7 rounded-[2rem] border border-gray-100 flex items-start justify-between shadow-sm hover:shadow-md transition-shadow">
    <div>
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">{title}</p>
      <h3 className="text-2xl font-black text-gray-900 mb-2">{value}</h3>
      <div className={`text-[10px] font-bold ${trendType === 'up' ? 'text-emerald-500' : 'text-blue-500'}`}>{trend}</div>
    </div>
    <div className="p-4 bg-gray-50 rounded-2xl text-gray-400">{icon}</div>
  </div>
);

const BudgetsView = ({ goals, transactions, formatMoney, lang, onAddClick, user }: any) => {
  const tStr = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStr.budgets}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStr.new_budget}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {goals.map((goal: any) => {
          const spent = transactions.filter((tr: any) => tr.category === goal.category).reduce((s: number, tr: any) => s + tr.amount, 0);
          const percent = Math.min((spent / goal.limit) * 100, 100);
          return (
            <div key={goal.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm group">
              <div className="flex justify-between mb-4">
                <div className="flex items-center gap-3">
                   <div className="p-2.5 bg-blue-50 text-blue-600 rounded-xl">{CATEGORY_ICONS[goal.category as Category]}</div>
                   <h3 className="font-bold">{(tStr.categories as any)[goal.category]}</h3>
                </div>
                <button onClick={() => dataService.deleteGoal(user.uid, goal.id)} className="text-gray-300 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
              </div>
              <div className="w-full h-2 bg-gray-50 rounded-full overflow-hidden mb-2"><div className={`h-full ${percent > 90 ? 'bg-red-500' : 'bg-blue-600'}`} style={{width: `${percent}%`}} /></div>
              <div className="flex justify-between text-[10px] font-bold text-gray-400 uppercase"><span>{formatMoney(spent)} / {formatMoney(goal.limit)}</span><span>{percent.toFixed(0)}%</span></div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const AccountsView = ({ accounts, formatMoney, lang, onAddClick, user }: any) => {
  const tStr = translations[lang];
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center"><h2 className="text-xl font-bold">{tStr.accounts}</h2><button onClick={onAddClick} className="text-blue-600 font-bold text-sm">+{tStr.new_account}</button></div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map((acc: any) => (
          <div key={acc.id} className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-[2.5rem] text-white shadow-xl relative group">
            <button onClick={() => dataService.deleteAccount(user.uid, acc.id)} className="absolute top-6 right-6 text-white/40 hover:text-white"><Trash2 className="w-4 h-4" /></button>
            <p className="text-[10px] uppercase font-bold opacity-70 mb-1">{(tStr.account_types as any)[acc.type]}</p>
            <h3 className="text-xl font-bold mb-6">{acc.name}</h3>
            <p className="text-3xl font-black">{formatMoney(acc.balance)}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

const BudgetForm = ({ onAdd, onClose, lang }: any) => {
  const tStr = translations[lang];
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [limit, setLimit] = useState('');
  return (
