export const dataService = {
  /**
   * Ensures the root user document exists with required fields like 'name'.
   * Matches the structure shown in your Firestore screenshot.
   */
  ensureUserProfile: async (userId: string, email: string) => {
    const userDocRef = doc(db, "users", userId);
    const userSnap = await getDoc(userDocRef);

    const defaultData = {
      email,
      lastLogin: serverTimestamp()
    };

    if (!userSnap.exists()) {
      // First time user: create the document with a default name
      return setDoc(userDocRef, {
        ...defaultData,
        name: email.split('@')[0], // Default name from email prefix
        createdAt: serverTimestamp(),
        uid: userId
      });
    } else {
      // Returning user: just update last login
      return setDoc(userDocRef, defaultData, { merge: true });
    }
  },

  // Settings
  subscribeToSettings: (userId: string, callback: (settings: UserSettings | null) => void) => {
    return onSnapshot(doc(db, "users", userId, "config", "preferences"), (doc) => {
