            <div className="flex items-center gap-3 mt-1.5 text-xs font-semibold text-gray-400">
              <span className="flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5" />
                {currentTime.toLocaleDateString(lang, { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
              <span>•</span>
              <span className="text-blue-600 font-bold">{currency.code}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setShowSettingsModal(true)} className="lg:hidden p-3 bg-white border border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 transition-colors shadow-sm">
                <Settings className="w-5 h-5" />
