             <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 lg:px-6 py-3 rounded-2xl font-bold shadow-xl shadow-blue-100 active:scale-95 transition-all text-sm">
               <Plus className="w-5 h-5" /> <span className="hidden sm:inline">{t.entry}</span>
             </button>
