              </span>
              <span className="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-full border border-gray-100 shadow-sm">
                <Clock className="w-3.5 h-3.5 text-blue-500" />
                {currentTime.toLocaleTimeString(lang, { hour: '2-digit', minute: '2-digit' })}
              </span>
              <span className="text-blue-600 font-black uppercase">{currency.code}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setShowSettingsModal(true)} className="lg:hidden p-3 bg-white border border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 transition-colors shadow-sm active:scale-95">
