      </nav>

      {/* Mobile Settings Modal */}
      {showSettingsModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-end lg:hidden animate-in fade-in duration-200" onClick={() => setShowSettingsModal(false)}>
