                       <button onClick={() => updateLanguage('en')} className={`flex-1 py-4 rounded-2xl text-sm font-bold border transition-all ${lang === 'en' ? 'bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}>English</button>
                       <button onClick={() => updateLanguage('ar')} className={`flex-1 py-4 rounded-2xl text-sm font-bold border transition-all ${lang === 'ar' ? 'bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}>العربية</button>
                    </div>
