                 <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-4">{t.currency}</label>
                    <select 
                       value={currency.code} 
                       onChange={(e) => updateCurrencyByCode(e.target.value)}
                       className="w-full py-5 px-6 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold text-gray-900 outline-none"
                    >
                       {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label} ({c.symbol})</option>)}
                    </select>
                 </div>

                 <button onClick={() => signOut(auth)} className="w-full flex items-center justify-center gap-3 py-5 text-rose-500 font-black bg-rose-50 rounded-2xl mt-6 active:scale-95 transition-all">
                    <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'تسجيل الخروج' : 'Sign Out'}
                 </button>
              </div>
           </div>
        </div>
      )}

      {showForm && <TransactionForm accounts={accounts} onAdd={(t) => dataService.addTransaction(user.uid, t)} onClose={() => setShowForm(false)} lang={lang} />}
      {showBudgetForm && <BudgetForm initialData={editingBudget} onAdd={(b: any) => dataService.saveGoal(user.uid, b)} onClose={() => { setShowBudgetForm(false); setEditingBudget(null); }} lang={lang} />}
      {showAccountForm && <AccountForm initialData={editingAccount} onAdd={(a: any) => dataService.saveAccount(user.uid, a)} onClose={() => { setShowAccountForm(false); setEditingAccount(null); }} lang={lang} />}
    </div>
  );
};

