            <div key={goal.id} className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm group hover:shadow-md transition-shadow">
              <div className="flex justify-between mb-6">
                <div className="flex items-center gap-4">
                   <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl">{CATEGORY_ICONS[goal.category as Category]}</div>
