                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => onEditClick(goal)} className="text-gray-200 hover:text-blue-500 transition-colors p-2"><Edit2 className="w-4 h-4" /></button>
                  <button onClick={() => dataService.deleteGoal(user.uid, goal.id)} className="text-gray-200 hover:text-rose-500 transition-colors p-2"><Trash2 className="w-4 h-4" /></button>
