              <button onClick={() => dataService.deleteAccount(user.uid, acc.id)} className="text-white/40 hover:text-white transition-colors"><Trash2 className="w-5 h-5" /></button>
            </div>
            <p className="text-[10px] uppercase font-black tracking-[0.25em] opacity-70 mb-2">{(tStr.account_types as any)[acc.type]}</p>
            <h3 className="text-xl font-bold mb-8 relative z-10">{acc.name}</h3>
            <p className="text-4xl font-black relative z-10">{formatMoney(acc.balance)}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

const BudgetForm = ({ onAdd, onClose, lang, initialData }: any) => {
  const tStr = translations[lang];
  const [category, setCategory] = useState<Category>(initialData?.category || CATEGORIES[0]);
  const [limit, setLimit] = useState(initialData?.limit?.toString() || '');
  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-[110] p-4 animate-in fade-in duration-200"><div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl animate-in zoom-in-95 duration-300"><h2 className="text-2xl font-black mb-8 text-gray-900">{initialData ? tStr.edit_budget : tStr.new_budget}</h2><div className="space-y-5"><select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-bold text-gray-800 cursor-pointer">{CATEGORIES.map(c => <option key={c} value={c}>{(tStr.categories as any)[c]}</option>)}</select><input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-black text-gray-900 text-xl" placeholder="0.00" /><div className="flex gap-4 pt-6"><button onClick={onClose} className="flex-1 font-bold text-gray-400 hover:text-gray-600 transition-colors uppercase tracking-widest text-xs">{tStr.cancel}</button><button onClick={() => { if(!limit) return; onAdd({ ...initialData, category, limit: Number(limit) }); onClose(); }} className="flex-1 bg-blue-600 hover:bg-blue-700 text-white p-5 rounded-2xl font-black shadow-xl shadow-blue-100 transition-all active:scale-95 uppercase tracking-widest text-xs">{initialData ? tStr.update : tStr.save}</button></div></div></div></div>
  );
};

const AccountForm = ({ onAdd, onClose, lang, initialData }: any) => {
  const tStr = translations[lang];
  const [name, setName] = useState(initialData?.name || '');
  const [type, setType] = useState<AccountType>(initialData?.type || 'Checking');
  const [balance, setBalance] = useState(initialData?.balance?.toString() || '');
  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-[110] p-4 animate-in fade-in duration-200"><div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl animate-in zoom-in-95 duration-300"><h2 className="text-2xl font-black mb-8 text-gray-900">{initialData ? tStr.edit_account : tStr.new_account}</h2><div className="space-y-5"><input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-bold text-gray-900" placeholder={tStr.account_name} /><select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-bold text-gray-800 cursor-pointer">{['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(at => <option key={at} value={at}>{(tStr.account_types as any)[at]}</option>)}</select><input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-black text-gray-900 text-xl" placeholder="0.00" /><div className="flex gap-4 pt-6"><button onClick={onClose} className="flex-1 font-bold text-gray-400 hover:text-gray-600 transition-colors uppercase tracking-widest text-xs">{tStr.cancel}</button><button onClick={() => { if(!name || !balance) return; onAdd({ ...initialData, name, type, balance: Number(balance) }); onClose(); }} className="flex-1 bg-blue-600 hover:bg-blue-700 text-white p-5 rounded-2xl font-black shadow-xl shadow-blue-100 transition-all active:scale-95 uppercase tracking-widest text-xs">{initialData ? tStr.update : tStr.create}</button></div></div></div></div>
  );
};

export default App;

export type Category = 
  | 'Food & Dining'
  | 'Transportation'
  | 'Shopping'
  | 'Entertainment'
  | 'Bills & Utilities'
  | 'Health'
  | 'Education'
  | 'Other';

export type Mood = 'Happy' | 'Stressed' | 'Tired' | 'Bored' | 'Excited' | 'Neutral';

export type Currency = {
  code: string;
  symbol: string;
  label: string;
};

export type AccountType = 'Checking' | 'Savings' | 'Credit Card' | 'Investment' | 'Cash';

export type ViewType = 'dashboard' | 'history' | 'budgets' | 'accounts' | 'profile' | 'statement';

/**
 * Interface for the root user document found in /users/{uid}
 */
export interface UserProfile {
  uid: string;
  email: string;
  name: string;
  photoURL?: string; // New: Optional profile picture URL
  createdAt: any; // Firestore Timestamp
  lastLogin: any; // Firestore Timestamp
}

export interface UserSettings {
  language: 'en' | 'ar';
  currency: Currency;
  updatedAt?: any; // Firestore Timestamp
}

export interface Account {
  id: string;
  userId: string;
  name: string;
  type: AccountType;
  balance: number;
  createdAt?: any;
}

export interface Transaction {
  id: string;
  userId: string;
  amount: number;
  category: Category;
  date: string; 
  time: string; 
  description: string;
  mood: Mood;
  accountId: string;
  createdAt?: any;
}

export interface BehavioralInsight {
  title: string;
  description: string;
  severity: 'neutral' | 'warning' | 'positive';
  type: 'pattern' | 'budget' | 'psychology';
}

export interface BudgetGoal {
  id: string;
  userId: string;
  category: Category;
  limit: number;
  createdAt?: any;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BehavioralInsight, BudgetGoal, Currency, Account, Category, AccountType, UserSettings, UserProfile, ViewType } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import AuthScreen from './components/AuthScreen';
import { getBehavioralInsights } from './services/geminiService';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  TrendingUp, Languages, LogOut, Loader2, Globe, Trash2, Settings, X, Calendar, Clock, Edit2, User as UserIcon, FileText, Camera
} from 'lucide-react';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>('en');
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showForm, setShowForm] = useState(false);
  const [editingBudget, setEditingBudget] = useState<BudgetGoal | null>(null);
  const [editingAccount, setEditingAccount] = useState<Account | null>(null);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [insights, setInsights] = useState<BehavioralInsight[]>([]);
  const [loadingInsights, setLoadingInsights] = useState(false);

  // Live clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (u) => {
      if (u) {
        await dataService.ensureUserProfile(u.uid, u.email || '');
      }
      setUser(u);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Data Sync
  useEffect(() => {
    if (!user) return;

    const unsubProfile = dataService.subscribeToUserProfile(user.uid, (profile) => {
      setUserProfile(profile);
    });

    const unsubSettings = dataService.subscribeToSettings(user.uid, (settings) => {
      if (settings) {
        setLang(settings.language);
        setCurrency(settings.currency);
      } else {
        dataService.saveSettings(user.uid, { language: lang, currency });
      }
    });

    const unsubT = dataService.subscribe(user.uid, 'transactions', (data: Transaction[]) => {
      setTransactions(data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    });

    const unsubG = dataService.subscribe(user.uid, 'goals', (data: BudgetGoal[]) => {
      if (data.length === 0) {
        INITIAL_GOALS.forEach(g => dataService.saveGoal(user.uid, { ...g, userId: user.uid } as any));
      } else {
        setGoals(data);
      }
    });

    const unsubA = dataService.subscribe(user.uid, 'accounts', (data: Account[]) => {
      if (data.length === 0) {
        const defaults = [
          { name: 'Cash Wallet', type: 'Cash' as AccountType, balance: 1000 },
          { name: 'Primary Bank', type: 'Checking' as AccountType, balance: 5000 }
        ];
        defaults.forEach(acc => dataService.saveAccount(user.uid, { ...acc, userId: user.uid } as any));
      } else {
        setAccounts(data);
      }
    });

    return () => {
      unsubProfile();
      unsubSettings();
      unsubT();
      unsubG();
      unsubA();
    };
  }, [user]);

  useEffect(() => {
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [lang]);

  const updateLanguage = (newLang: Language) => {
    setLang(newLang);
    if (user) dataService.saveSettings(user.uid, { language: newLang, currency });
  };

  const updateCurrencyByCode = (code: string) => {
    const selected = CURRENCIES.find(c => c.code === code);
    if (selected) {
      setCurrency(selected);
      if (user) dataService.saveSettings(user.uid, { language: lang, currency: selected });
    }
  };

  const refreshInsights = useCallback(async () => {
    if (transactions.length < 3) return;
    setLoadingInsights(true);
    try {
      const newInsights = await getBehavioralInsights(transactions, goals, lang);
      setInsights(newInsights);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingInsights(false);
    }
  }, [transactions, goals, lang]);

  useEffect(() => {
    if (user && transactions.length > 0) refreshInsights();
  }, [transactions.length, user, refreshInsights]);

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalSpent = useMemo(() => transactions.reduce((acc, curr) => acc + curr.amount, 0), [transactions]);
  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const userName = useMemo(() => {
    if (userProfile?.name) return userProfile.name;
    const emailStr = user?.email || '';
    if (user?.displayName) return user.displayName;
    if (emailStr.includes('@')) return emailStr.split('@')[0];
    return emailStr || 'User';
  }, [user, userProfile]);

  if (authLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#f8fafc]">
        <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
        <p className="text-gray-400 font-bold uppercase tracking-widest text-[10px]">Verifying Identity...</p>
      </div>
    );
  }

  if (!user) {
    return <AuthScreen lang={lang} onLanguageToggle={() => updateLanguage(lang === 'en' ? 'ar' : 'en')} />;
  }

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-[#f8fafc]" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      {/* Sidebar */}
      <nav className={`fixed ${lang === 'ar' ? 'right-0' : 'left-0'} top-0 h-full w-64 bg-white border-${lang === 'ar' ? 'l' : 'r'} border-gray-100 p-6 hidden lg:flex flex-col z-30`}>
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-black bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-700 tracking-tight">FinSense AI</span>
        </div>
        <div className="space-y-2 overflow-y-auto max-h-[70vh] custom-scrollbar pr-2">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label={t.overview} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label={t.history} active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label={t.budgets} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label={t.accounts} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
          <NavLink icon={<FileText className="w-5 h-5" />} label={t.statement} active={activeView === 'statement'} onClick={() => setActiveView('statement')} />
          <NavLink icon={<UserIcon className="w-5 h-5" />} label={t.profile} active={activeView === 'profile'} onClick={() => setActiveView('profile')} />
        </div>

        <div className="mt-auto space-y-4">
           {userProfile?.photoURL ? (
             <div className="px-5 py-2 flex items-center gap-3">
                <img src={userProfile.photoURL} alt="Profile" className="w-10 h-10 rounded-xl object-cover border border-gray-100 shadow-sm" />
                <div>
                   <p className="text-xs font-black text-gray-900 truncate max-w-[120px]">{userName}</p>
                   <p className="text-[10px] font-bold text-gray-400 truncate max-w-[120px]">{userProfile.email}</p>
                </div>
             </div>
           ) : (
              <div className="px-5 py-2 flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center text-sm font-black border border-blue-100">
                   {userName.charAt(0).toUpperCase()}
                </div>
                <div>
                   <p className="text-xs font-black text-gray-900 truncate max-w-[120px]">{userName}</p>
                   <p className="text-[10px] font-bold text-gray-400 truncate max-w-[120px]">{userProfile?.email || user.email}</p>
                </div>
              </div>
           )}

           <button onClick={() => signOut(auth)} className="w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold text-rose-500 hover:bg-rose-50 transition-all mb-4">
             <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'خروج' : 'Logout'}
           </button>

           <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100">
             <div className="flex items-center gap-2 mb-3 text-blue-600">
                <Languages className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.language}</span>
             </div>
             <div className="flex gap-1 bg-white p-1 rounded-xl shadow-sm">
                <button onClick={() => updateLanguage('en')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'en' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>EN</button>
                <button onClick={() => updateLanguage('ar')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'ar' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>AR</button>
             </div>
           </div>

           <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
             <div className="flex items-center gap-2 mb-3 text-gray-500">
                <Globe className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.currency}</span>
             </div>
             <select 
               value={currency.code} 
               onChange={(e) => updateCurrencyByCode(e.target.value)}
               className="bg-white border border-gray-100 text-xs font-bold text-gray-700 outline-none w-full p-2.5 rounded-xl shadow-sm cursor-pointer"
             >
               {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label} ({c.symbol})</option>)}
             </select>
           </div>
        </div>
      </nav>

      <main className={`${lang === 'ar' ? 'lg:mr-64' : 'lg:ml-64'} p-4 lg:p-10 max-w-7xl mx-auto min-h-screen`}>
        <header className="flex justify-between items-start mb-10">
          <div>
            <h1 className="text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
              {activeView === 'dashboard' ? `${t.welcome_back}, ${userName}` : (t as any)[activeView] || t.overview}
            </h1>
            <div className="flex items-center gap-4 mt-2 text-xs font-bold text-gray-400">
              <span className="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-full border border-gray-100 shadow-sm">
                <Calendar className="w-3.5 h-3.5 text-blue-500" />
                {currentTime.toLocaleDateString(lang, { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
              <span className="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-full border border-gray-100 shadow-sm">
                <Clock className="w-3.5 h-3.5 text-blue-500" />
                {currentTime.toLocaleTimeString(lang, { hour: '2-digit', minute: '2-digit' })}
              </span>
              <span className="text-blue-600 font-black uppercase">{currency.code}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setShowSettingsModal(true)} className="lg:hidden p-3 bg-white border border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 transition-colors shadow-sm active:scale-95">
                <Settings className="w-5 h-5" />
             </button>
             <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 lg:px-6 py-3.5 rounded-2xl font-black shadow-xl shadow-blue-100 active:scale-95 transition-all text-sm">
               <Plus className="w-5 h-5" /> <span className="hidden sm:inline uppercase tracking-widest">{t.entry}</span>
             </button>
          </div>
        </header>

        {activeView === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
              <StatCard title={t.total_expenses} value={formatMoney(totalSpent)} trend={t.trend_monthly} trendType="down" icon={<Wallet className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.total_assets} value={formatMoney(totalBalance)} trend={t.trend_liquid} trendType="up" icon={<TrendingUp className="w-5 h-5" />} lang={lang} />
              <StatCard title={t.budget_health} value={`${goals.length}`} trend={t.trend_goals} trendType="up" icon={<Target className="w-5 h-5" />} lang={lang} />
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
              <div className="xl:col-span-2 space-y-8"><Charts transactions={transactions} lang={lang} /></div>
              <div className="xl:col-span-1"><AIInsights insights={insights} loading={loadingInsights} onRefresh={refreshInsights} lang={lang} /></div>
            </div>
          </div>
        )}
        {activeView === 'history' && <TransactionList transactions={transactions} onDelete={(id) => dataService.deleteTransaction(user.uid, id)} lang={lang} />}
        {activeView === 'budgets' && (
          <BudgetsView 
            user={user} 
            goals={goals} 
            transactions={transactions} 
            formatMoney={formatMoney} 
            lang={lang} 
            onAddClick={() => { setEditingBudget(null); setShowBudgetForm(true); }} 
            onEditClick={(goal: BudgetGoal) => { setEditingBudget(goal); setShowBudgetForm(true); }}
          />
        )}
        {activeView === 'accounts' && (
          <AccountsView 
            user={user} 
            accounts={accounts} 
            formatMoney={formatMoney} 
            lang={lang} 
            onAddClick={() => { setEditingAccount(null); setShowAccountForm(true); }} 
            onEditClick={(acc: Account) => { setEditingAccount(acc); setShowAccountForm(true); }}
          />
        )}
        {activeView === 'profile' && <ProfileView profile={userProfile} lang={lang} transactionsCount={transactions.length} accountsCount={accounts.length} />}
        {activeView === 'statement' && <StatementView accounts={accounts} transactions={transactions} currency={currency} lang={lang} />}
      </main>

      {/* Mobile Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-100 px-2 py-4 flex justify-around items-center lg:hidden z-40 shadow-[0_-10px_40px_rgba(0,0,0,0.03)] rounded-t-[2.5rem]">
        <MobileNavLink icon={<LayoutDashboard className="w-5 h-5" />} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
        <MobileNavLink icon={<History className="w-5 h-5" />} active={activeView === 'history'} onClick={() => setActiveView('history')} />
        <MobileNavLink icon={<Target className="w-5 h-5" />} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
        <button onClick={() => setShowForm(true)} className="w-12 h-12 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center -translate-y-8 active:scale-90 transition-transform"><Plus className="w-6 h-6" /></button>
        <MobileNavLink icon={<CreditCard className="w-5 h-5" />} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
        <MobileNavLink icon={<FileText className="w-5 h-5" />} active={activeView === 'statement'} onClick={() => setActiveView('statement')} />
        <MobileNavLink icon={<UserIcon className="w-5 h-5" />} active={activeView === 'profile'} onClick={() => setActiveView('profile')} />
      </nav>

      {/* Mobile Settings Modal */}
      {showSettingsModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-end lg:hidden animate-in fade-in duration-200" onClick={() => setShowSettingsModal(false)}>
           <div className="bg-white w-full rounded-t-[3rem] p-10 animate-in slide-in-from-bottom duration-300" onClick={e => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-10">
                 <h2 className="text-2xl font-black text-gray-900">{t.settings}</h2>
                 <button onClick={() => setShowSettingsModal(false)} className="p-3 bg-gray-50 rounded-full active:scale-90"><X className="w-5 h-5 text-gray-400" /></button>
              </div>

              <div className="space-y-8">
                 <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-4">{t.language}</label>
                    <div className="flex gap-3">
                       <button onClick={() => updateLanguage('en')} className={`flex-1 py-4 rounded-2xl text-sm font-bold border transition-all ${lang === 'en' ? 'bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}>English</button>
                       <button onClick={() => updateLanguage('ar')} className={`flex-1 py-4 rounded-2xl text-sm font-bold border transition-all ${lang === 'ar' ? 'bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}>العربية</button>
                    </div>
