const ProfileView = ({ profile, lang, transactionsCount, accountsCount }: { profile: UserProfile | null, lang: Language, transactionsCount: number, accountsCount: number }) => {
  const t = translations[lang];
  const [name, setName] = useState(profile?.name || '');
  const [photoURL, setPhotoURL] = useState(profile?.photoURL || '');
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (profile?.name) setName(profile.name);
    if (profile?.photoURL) setPhotoURL(profile.photoURL);
  }, [profile]);

  const handleUpdate = async () => {
    if (!profile?.uid) return;
    setLoading(true);
    try {
      await dataService.updateUserProfile(profile.uid, { name, photoURL });
    } finally {
      setLoading(false);
    }
  };

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoURL(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const initialChar = (profile?.name || profile?.email || 'U').charAt(0).toUpperCase();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl">
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
        <div className="flex items-center gap-6 mb-10">
          <div className="relative group cursor-pointer" onClick={handleImageClick}>
            <div className="w-24 h-24 bg-blue-100 text-blue-600 rounded-[2.5rem] flex items-center justify-center text-3xl font-black overflow-hidden border-2 border-white shadow-xl shadow-blue-50 transition-transform group-hover:scale-105">
              {photoURL ? (
                <img src={photoURL} alt="Avatar" className="w-full h-full object-cover" />
              ) : (
                initialChar
              )}
            </div>
            <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-2 rounded-xl shadow-lg border-2 border-white transition-transform group-hover:scale-110">
              <Camera className="w-4 h-4" />
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileChange} 
            />
          </div>
          <div>
            <h2 className="text-2xl font-black text-gray-900">{profile?.name || 'User'}</h2>
            <p className="text-gray-400 font-bold text-sm">{profile?.email}</p>
          </div>
        </div>

        <div className="space-y-6">
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.full_name}</label>
            <input 
              type="text" 
              value={name} 
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-gray-50 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-800 focus:bg-white focus:border-blue-100 transition-colors"
            />
          </div>
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.email_address}</label>
            <input 
              disabled
              type="text" 
              value={profile?.email || ''} 
              className="w-full bg-gray-100 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-400 cursor-not-allowed"
            />
          </div>
          <button 
            onClick={handleUpdate}
            disabled={loading || (name === profile?.name && photoURL === profile?.photoURL)}
