              <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-widest"><span>{formatMoney(spent)} / {formatMoney(goal.limit)}</span><span className={percent > 90 ? 'text-rose-500' : 'text-blue-600'}>{percent.toFixed(0)}%</span></div>
