      {/* Preferences Section: Language & Currency */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
        <div>
          <h3 className="text-lg font-black text-gray-900 mb-6 flex items-center gap-2">
