const StatementView = ({ accounts, transactions, currency, lang }: { accounts: Account[], transactions: Transaction[], currency: Currency, lang: Language }) => {
  const t = translations[lang];
  const [selectedAccountId, setSelectedAccountId] = useState(accounts[0]?.id || '');
  const [period, setPeriod] = useState<'current' | 'last' | 'custom'>('current');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');

  useEffect(() => {
    if (!selectedAccountId && accounts.length > 0) {
      setSelectedAccountId(accounts[0].id);
    }
  }, [accounts, selectedAccountId]);

  const filteredTransactions = useMemo(() => {
    if (!selectedAccountId) return [];
    let list = transactions.filter(tr => tr.accountId === selectedAccountId);
    const now = new Date();

    if (period === 'current') {
      list = list.filter(tr => {
        const d = new Date(tr.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
      });
    } else if (period === 'last') {
      list = list.filter(tr => {
        const d = new Date(tr.date);
        const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1);
        return d.getMonth() === lastMonth.getMonth() && d.getFullYear() === lastMonth.getFullYear();
      });
    } else if (period === 'custom') {
      if (dateFrom) {
        list = list.filter(tr => new Date(tr.date) >= new Date(dateFrom));
      }
      if (dateTo) {
        list = list.filter(tr => new Date(tr.date) <= new Date(dateTo));
      }
    }

    return list.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [transactions, selectedAccountId, period, dateFrom, dateTo]);

  const selectedAccount = accounts.find(a => a.id === selectedAccountId);
  const currentBalance = selectedAccount?.balance || 0;

  const format = (val: number) => `${currency.symbol} ${val.toLocaleString(lang, { minimumFractionDigits: 2 })}`;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8">
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
          <div>
            <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.select_account}</label>
            <select 
              value={selectedAccountId} 
              onChange={(e) => setSelectedAccountId(e.target.value)}
              className="w-full bg-gray-50 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-800 focus:bg-white focus:ring-2 focus:ring-blue-100 transition-all"
            >
              {accounts.length === 0 && <option value="">No Accounts</option>}
              {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
            </select>
          </div>
          <div>
            <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.period}</label>
            <div className="flex flex-wrap gap-2">
              {(['current', 'last', 'custom'] as const).map(p => (
                <button 
                  key={p}
                  onClick={() => setPeriod(p)}
                  className={`px-4 py-3 rounded-xl text-xs font-bold border transition-all ${period === p ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                >
                  {(t as any)[p] || p}
                </button>
              ))}
            </div>
          </div>
        </div>

        {period === 'custom' && (
