        <div className="space-y-5">
          <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-bold text-gray-900" placeholder={tStr.account_name} />
          <select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-bold text-gray-800 cursor-pointer">
