          </select>

          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{tStr.initial_balance}</label>
            <input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border border-gray-100 p-5 rounded-2xl bg-gray-50 outline-none font-black text-gray-900 text-xl" placeholder="0.00" />
          </div>

          {type === 'Credit Card' && (
            <div className="animate-in slide-in-from-top-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{tStr.credit_limit}</label>
              <input type="number" value={creditLimit} onChange={e => setCreditLimit(e.target.value)} className="w-full border border-rose-100 p-5 rounded-2xl bg-rose-50/50 outline-none font-black text-rose-900 text-xl" placeholder="26000.00" />
            </div>
          )}

          <div className="flex gap-4 pt-6">
            <button onClick={onClose} className="flex-1 font-bold text-gray-400 hover:text-gray-600 transition-colors uppercase tracking-widest text-xs">{tStr.cancel}</button>
