              if(!name || !balance) return; 
              onAdd({ 
                ...initialData, 
                name, 
                type, 
                balance: Number(balance),
                creditLimit: type === 'Credit Card' ? Number(creditLimit) : undefined
              }); 
              onClose(); 
            }} className="flex-1 bg-blue-600 hover:bg-blue-700 text-white p-5 rounded-2xl font-black shadow-xl shadow-blue-100 transition-all active:scale-95 uppercase tracking-widest text-xs">{initialData ? tStr.update : tStr.create}</button>
          </div>
        </div>
      </div>
    </div>
  );
};

