            {['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(at => <option key={at} value={at}>{(tStr.account_types as any)[at]}</option>)}
          </select>

          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{tStr.initial_balance}</label>
            <input type="number" value={balance} onChange={e => setBalance(e.target.value)} className="w-full border border-gray-100 p-4 lg:p-5 rounded-2xl bg-gray-50 outline-none font-black text-gray-900 text-lg lg:text-xl" placeholder="0.00" />
          </div>

          {type === 'Credit Card' && (
            <div className="animate-in slide-in-from-top-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{tStr.credit_limit}</label>
              <input type="number" value={creditLimit} onChange={e => setCreditLimit(e.target.value)} className="w-full border border-rose-100 p-4 lg:p-5 rounded-2xl bg-rose-50/50 outline-none font-black text-rose-900 text-lg lg:text-xl" placeholder="26000.00" />
            </div>
          )}

          <div className="flex gap-4 pt-6">
            <button onClick={onClose} className="flex-1 font-bold text-gray-400 hover:text-gray-600 transition-colors uppercase tracking-widest text-[10px] lg:text-xs">{tStr.cancel}</button>
            <button onClick={() => { 
              if(!name || !balance) return; 
              onAdd({ 
                ...initialData, 
                name, 
                type, 
                balance: Number(balance),
                creditLimit: type === 'Credit Card' ? Number(creditLimit) : undefined
              }); 
              onClose(); 
            }} className="flex-1 bg-blue-600 hover:bg-blue-700 text-white p-4 lg:p-5 rounded-2xl font-black shadow-xl shadow-blue-100 transition-all active:scale-95 uppercase tracking-widest text-[10px] lg:text-xs">{initialData ? tStr.update : tStr.create}</button>
          </div>
        </div>
      </div>
    </div>
  );
};

