import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, BehavioralInsight, BudgetGoal } from "../types";

export const getBehavioralInsights = async (
  transactions: Transaction[],
  goals: BudgetGoal[],
  lang: 'en' | 'ar' = 'en'
): Promise<BehavioralInsight[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  const sanitizedTransactions = transactions.slice(0, 50).map(t => ({
    amount: t.amount,
    category: t.category,
    date: t.date,
    time: t.time,
    description: t.description,
    mood: t.mood
  }));

  const sanitizedGoals = goals.map(g => ({
    category: g.category,
    limit: g.limit
  }));

  const prompt = `
    Analyze these personal finance transactions and budget goals. 
    Provide exactly 3 factual, neutral behavioral insights. 

    NEUTRAL FEEDBACK STYLE:
    - Instead of "You spend too much on coffee", say "You have made 5 transactions at coffee shops this week, totaling $42.00".
    - Instead of "Stop ordering food late", say "Food delivery spending increases by 40% after 9pm".
    - Instead of "Great job saving", say "Current spending for 'Shopping' is at 12% of the monthly limit with 10 days remaining".

    CRITICAL: YOU MUST PROVIDE THE RESPONSE IN THE FOLLOWING LANGUAGE: ${lang === 'ar' ? 'Arabic (العربية)' : 'English'}.

    Data:
    Transactions: ${JSON.stringify(sanitizedTransactions)}
    Budget Goals: ${JSON.stringify(sanitizedGoals)}

    Output must be JSON only.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { 
                type: Type.STRING, 
                description: 'Values: neutral, warning, positive' 
              },
              type: { 
                type: Type.STRING, 
                description: 'Values: pattern, budget, psychology' 
              }
            },
            required: ["title", "description", "severity", "type"]
          }
        }
      }
    });

    const result = JSON.parse(response.text || "[]");
    return result;
  } catch (error: any) {
    console.error("Error fetching insights:", error);
    return [{
      title: lang === 'ar' ? "تحليل البيانات متوقف مؤقتاً" : "Data Analysis Paused",
      description: lang === 'ar' ? "نواجه مشكلة في الوصول للذكاء الاصطناعي. حاول مرة أخرى." : "We're having trouble reaching the AI. Try again in a moment.",
      severity: "neutral",
      type: "pattern"
    }];
  }
};

