const ProfileView = ({ profile, lang, updateLanguage, currency, updateCurrencyByCode, transactionsCount, accountsCount }: { 
  profile: UserProfile | null, 
  lang: Language, 
  updateLanguage: (l: Language) => void,
  currency: Currency,
  updateCurrencyByCode: (c: string) => void,
  transactionsCount: number, 
  accountsCount: number 
}) => {
  const t = translations[lang];
  const [name, setName] = useState(profile?.name || '');
  const [photoURL, setPhotoURL] = useState(profile?.photoURL || '');
  const [loading, setLoading] = useState(false);
  const [photoLoading, setPhotoLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (profile?.name) setName(profile.name);
    if (profile?.photoURL) setPhotoURL(profile.photoURL);
  }, [profile]);

  const compressImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_DIM = 200;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_DIM) {
            height *= MAX_DIM / width;
            width = MAX_DIM;
          }
        } else {
          if (height > MAX_DIM) {
            width *= MAX_DIM / height;
            height = MAX_DIM;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return resolve(base64Str);
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.4)); 
      };
      img.onerror = () => resolve(base64Str);
    });
  };

  const handleUpdate = async () => {
    if (!profile?.uid) return;
    setLoading(true);
    try {
      await dataService.updateUserProfile(profile.uid, { name, photoURL });
    } finally {
      setLoading(false);
    }
  };

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && profile?.uid) {
      setPhotoLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        const compressed = await compressImage(base64);
        setPhotoURL(compressed);
        try {
          await dataService.updateUserProfile(profile.uid, { photoURL: compressed });
        } catch (err) {
          console.error("Auto-save failed:", err);
        } finally {
          setPhotoLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const initialChar = (profile?.name || profile?.email || 'U').charAt(0).toUpperCase();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl space-y-6 lg:space-y-8">
      <div className="bg-white p-6 lg:p-8 rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm">
        <div className="flex items-center gap-6 mb-10">
          <div className="relative group cursor-pointer" onClick={handleImageClick}>
            <div className="w-20 h-20 lg:w-24 lg:h-24 bg-blue-100 text-blue-600 rounded-3xl lg:rounded-[2.5rem] flex items-center justify-center text-3xl font-black overflow-hidden border-2 border-white shadow-xl shadow-blue-50 transition-transform group-hover:scale-105">
              {photoLoading ? (
                <div className="flex flex-col items-center justify-center">
                  <Loader2 className="w-6 h-6 animate-spin mb-1" />
                  <span className="text-[8px] font-black uppercase">Saving</span>
                </div>
              ) : photoURL ? (
                <img src={photoURL} alt="Avatar" className="w-full h-full object-cover" />
              ) : (
                initialChar
              )}
            </div>
            <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-2 rounded-xl shadow-lg border-2 border-white transition-transform group-hover:scale-110 pointer-events-none">
              <Camera className="w-4 h-4" />
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileChange}
              onClick={(e) => (e.target as HTMLInputElement).value = ''}
            />
          </div>
          <div>
            <h2 className="text-xl lg:text-2xl font-black text-gray-900">{profile?.name || 'User'}</h2>
            <p className="text-gray-400 font-bold text-xs lg:text-sm">{profile?.email}</p>
          </div>
        </div>

        <div className="space-y-6">
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.full_name}</label>
            <input 
              type="text" 
              value={name} 
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-gray-50 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-800 focus:bg-white focus:border-blue-100 transition-colors text-sm"
            />
          </div>
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.email_address}</label>
            <input 
              disabled
              type="text" 
              value={profile?.email || ''} 
              className="w-full bg-gray-100 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-400 cursor-not-allowed text-sm"
            />
          </div>
          <button 
            onClick={handleUpdate}
            disabled={loading || (name === profile?.name && photoURL === profile?.photoURL)}
            className="w-full bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white p-4 lg:p-5 rounded-2xl font-black shadow-xl shadow-blue-100 transition-all active:scale-95 uppercase tracking-widest text-[10px] lg:text-xs"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : t.update_profile}
          </button>
        </div>

        <div className="grid grid-cols-2 gap-4 mt-8 lg:mt-10 pt-8 lg:pt-10 border-t border-gray-50">
           <div className="text-center">
              <p className="text-xl lg:text-2xl font-black text-gray-900">{transactionsCount}</p>
              <p className="text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.history}</p>
           </div>
           <div className="text-center">
              <p className="text-xl lg:text-2xl font-black text-gray-900">{accountsCount}</p>
              <p className="text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.accounts}</p>
           </div>
        </div>
      </div>

      <div className="bg-white p-6 lg:p-8 rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm space-y-6 lg:space-y-8">
        <div>
          <h3 className="text-base lg:text-lg font-black text-gray-900 mb-6 flex items-center gap-2">
            <Globe className="w-5 h-5 text-blue-600" />
            {lang === 'ar' ? 'التفضيلات' : 'Preferences'}
          </h3>

          <div className="space-y-6">
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-4">{t.language}</label>
              <div className="flex gap-3">
                <button 
                  onClick={() => updateLanguage('en')} 
                  className={`flex-1 py-3 lg:py-4 rounded-2xl text-xs lg:text-sm font-bold border transition-all ${lang === 'en' ? 'bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                >
                  English
                </button>
                <button 
                  onClick={() => updateLanguage('ar')} 
                  className={`flex-1 py-3 lg:py-4 rounded-2xl text-xs lg:text-sm font-bold border transition-all ${lang === 'ar' ? 'bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                >
                  العربية
                </button>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-4">{t.currency}</label>
              <select 
                value={currency.code} 
                onChange={(e) => updateCurrencyByCode(e.target.value)}
                className="w-full py-4 lg:py-5 px-6 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold text-gray-900 outline-none focus:bg-white focus:border-blue-100 transition-colors"
              >
                {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label} ({c.symbol})</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-rose-50/50 p-6 rounded-3xl lg:rounded-[2.5rem] border border-rose-100">
         <button 
            onClick={() => signOut(auth)} 
            className="w-full flex items-center justify-center gap-3 py-4 lg:py-5 text-rose-500 font-black bg-white rounded-2xl shadow-sm hover:shadow-md transition-all active:scale-95 border border-rose-100 uppercase tracking-widest text-[10px] lg:text-xs"
         >
            <LogOut className="w-5 h-5" />
            {lang === 'ar' ? 'تسجيل الخروج' : 'Sign Out'}
         </button>
      </div>
    </div>
  );
};

const StatementView = ({ accounts, transactions, currency, lang }: { accounts: Account[], transactions: Transaction[], currency: Currency, lang: Language }) => {
  const t = translations[lang];
  const [selectedAccountId, setSelectedAccountId] = useState(accounts[0]?.id || '');
  const [period, setPeriod] = useState<'current' | 'last' | 'custom'>('current');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');

  useEffect(() => {
    if (!selectedAccountId && accounts.length > 0) {
      setSelectedAccountId(accounts[0].id);
    }
  }, [accounts, selectedAccountId]);

  const filteredTransactions = useMemo(() => {
    if (!selectedAccountId) return [];
    let list = transactions.filter(tr => tr.accountId === selectedAccountId);
    const now = new Date();

    if (period === 'current') {
      list = list.filter(tr => {
        const d = new Date(tr.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
      });
    } else if (period === 'last') {
      list = list.filter(tr => {
        const d = new Date(tr.date);
        const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1);
        return d.getMonth() === lastMonth.getMonth() && d.getFullYear() === lastMonth.getFullYear();
      });
    } else if (period === 'custom') {
      if (dateFrom) {
        list = list.filter(tr => new Date(tr.date) >= new Date(dateFrom));
      }
      if (dateTo) {
        list = list.filter(tr => new Date(tr.date) <= new Date(dateTo));
      }
    }

    return list.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [transactions, selectedAccountId, period, dateFrom, dateTo]);

  const selectedAccount = accounts.find(a => a.id === selectedAccountId);
  const currentBalance = selectedAccount?.balance || 0;

  const format = (val: number) => `${currency.symbol} ${val.toLocaleString(lang, { minimumFractionDigits: 2 })}`;

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6 lg:space-y-8">
      <div className="bg-white p-6 lg:p-8 rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm relative overflow-hidden">
        <div className="flex justify-between items-start mb-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 lg:gap-8 flex-1">
            <div>
              <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.select_account}</label>
              <select 
                value={selectedAccountId} 
                onChange={(e) => setSelectedAccountId(e.target.value)}
                className="w-full bg-gray-50 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-800 focus:bg-white focus:ring-2 focus:ring-blue-100 transition-all text-sm"
              >
                {accounts.length === 0 && <option value="">No Accounts</option>}
                {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.period}</label>
              <div className="flex flex-wrap gap-2">
                {(['current', 'last', 'custom'] as const).map(p => (
                  <button 
                    key={p}
                    onClick={() => setPeriod(p)}
                    className={`px-3 lg:px-4 py-3 rounded-xl text-[10px] lg:text-xs font-bold border transition-all ${period === p ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                  >
                    {(t as any)[p] || p}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <button 
            onClick={handlePrint}
            className="ms-4 p-4 bg-gray-50 hover:bg-white border border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 shadow-sm transition-all active:scale-95 group"
            title={lang === 'ar' ? 'طباعة' : 'Print Statement'}
          >
            <Printer className="w-5 h-5" />
          </button>
        </div>

        {period === 'custom' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-8 p-6 bg-gray-50 rounded-3xl animate-in slide-in-from-top-2 border border-blue-50">
            <div>
              <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-2">{t.date_from}</label>
              <input 
                type="date" 
                value={dateFrom} 
                onChange={e => setDateFrom(e.target.value)}
                className="w-full bg-white border border-gray-200 p-4 rounded-xl outline-none text-sm font-bold text-gray-800 focus:ring-2 focus:ring-blue-500/20 transition-all"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.date_to}</label>
              <input 
                type="date" 
                value={dateTo} 
                onChange={e => setDateTo(e.target.value)}
                className="w-full bg-white border border-gray-200 p-4 rounded-xl outline-none text-sm font-bold text-gray-800 focus:ring-2 focus:ring-blue-500/20 transition-all"
              />
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-6 bg-blue-50/50 rounded-3xl border border-blue-100">
           <div>
              <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1">{t.summary}</p>
              <p className="text-sm font-bold text-blue-900">{selectedAccount?.name || '---'}</p>
           </div>
           <div>
              <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1">{t.ending_balance}</p>
              <p className="text-base lg:text-lg font-black text-blue-600">{format(currentBalance)}</p>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
        <table className="w-full text-start">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{t.date}</th>
              <th className="px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{t.description}</th>
              <th className="hidden sm:table-cell px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{t.category}</th>
              <th className="px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-end">{t.amount}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredTransactions.map(tr => (
              <tr key={tr.id}>
                <td className="px-6 lg:px-8 py-4 lg:py-5 text-xs lg:text-sm font-bold text-gray-500">{tr.date}</td>
                <td className="px-6 lg:px-8 py-4 lg:py-5 text-xs lg:text-sm font-bold text-gray-800">{tr.description}</td>
                <td className="hidden sm:table-cell px-6 lg:px-8 py-4 lg:py-5 text-[10px] lg:text-xs font-bold text-blue-600">{(t.categories as any)[tr.category]}</td>
                <td className="px-6 lg:px-8 py-4 lg:py-5 text-xs lg:text-sm font-black text-gray-900 text-end">-{format(tr.amount)}</td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr><td colSpan={4} className="px-6 lg:px-8 py-10 text-center text-gray-400 font-bold italic">{t.no_transactions}</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

