              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{tStr.credit_limit}</label>
              <input type="number" value={creditLimit} onChange={e => setCreditLimit(e.target.value)} className="w-full border border-rose-100 p-4 lg:p-5 rounded-2xl bg-rose-50/50 outline-none font-black text-rose-900 text-lg lg:text-xl" placeholder="26000.00" />
