const StatementView = ({ accounts, transactions, currency, lang }: { accounts: Account[], transactions: Transaction[], currency: Currency, lang: Language }) => {
  const t = translations[lang];
  const [selectedAccountId, setSelectedAccountId] = useState(accounts[0]?.id || '');
  const [period, setPeriod] = useState<'current' | 'last' | 'custom'>('current');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');

  useEffect(() => {
    if (!selectedAccountId && accounts.length > 0) {
      setSelectedAccountId(accounts[0].id);
    }
  }, [accounts, selectedAccountId]);

  const filteredTransactions = useMemo(() => {
    if (!selectedAccountId) return [];
    let list = transactions.filter(tr => tr.accountId === selectedAccountId);
    const now = new Date();

    if (period === 'current') {
      list = list.filter(tr => {
        const d = new Date(tr.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
      });
    } else if (period === 'last') {
      list = list.filter(tr => {
        const d = new Date(tr.date);
        const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1);
        return d.getMonth() === lastMonth.getMonth() && d.getFullYear() === lastMonth.getFullYear();
      });
    } else if (period === 'custom') {
      if (dateFrom) {
        list = list.filter(tr => new Date(tr.date) >= new Date(dateFrom));
      }
      if (dateTo) {
        list = list.filter(tr => new Date(tr.date) <= new Date(dateTo));
      }
    }

    return list.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [transactions, selectedAccountId, period, dateFrom, dateTo]);

  const selectedAccount = accounts.find(a => a.id === selectedAccountId);
  const currentBalance = selectedAccount?.balance || 0;

  const format = (val: number) => `${currency.symbol} ${val.toLocaleString(lang, { minimumFractionDigits: 2 })}`;

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6 lg:space-y-8">
      <div className="bg-white p-6 lg:p-8 rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm relative overflow-hidden">
        <div className="flex justify-between items-start mb-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 lg:gap-8 flex-1">
            <div>
              <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.select_account}</label>
              <select 
                value={selectedAccountId} 
                onChange={(e) => setSelectedAccountId(e.target.value)}
                className="w-full bg-gray-50 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-800 focus:bg-white focus:ring-2 focus:ring-blue-100 transition-all text-sm"
              >
                {accounts.length === 0 && <option value="">No Accounts</option>}
                {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.period}</label>
              <div className="flex flex-wrap gap-2">
                {(['current', 'last', 'custom'] as const).map(p => (
                  <button 
                    key={p}
                    onClick={() => setPeriod(p)}
                    className={`px-3 lg:px-4 py-3 rounded-xl text-[10px] lg:text-xs font-bold border transition-all ${period === p ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                  >
                    {(t as any)[p] || p}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <button 
            onClick={handlePrint}
            className="ms-4 p-4 bg-gray-50 hover:bg-white border border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 shadow-sm transition-all active:scale-95 group"
            title={lang === 'ar' ? 'طباعة' : 'Print Statement'}
          >
            <Printer className="w-5 h-5" />
          </button>
        </div>

        {period === 'custom' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-8 p-6 bg-gray-50 rounded-3xl animate-in slide-in-from-top-2 border border-blue-50">
            <div>
              <label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-2">{t.date_from}</label>
              <input 
                type="date" 
                value={dateFrom} 
                onChange={e => setDateFrom(e.target.value)}
                className="w-full bg-white border border-gray-200 p-4 rounded-xl outline-none text-sm font-bold text-gray-800 focus:ring-2 focus:ring-blue-500/20 transition-all"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.date_to}</label>
              <input 
                type="date" 
                value={dateTo} 
                onChange={e => setDateTo(e.target.value)}
                className="w-full bg-white border border-gray-200 p-4 rounded-xl outline-none text-sm font-bold text-gray-800 focus:ring-2 focus:ring-blue-500/20 transition-all"
              />
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-6 bg-blue-50/50 rounded-3xl border border-blue-100">
           <div>
              <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1">{t.summary}</p>
              <p className="text-sm font-bold text-blue-900">{selectedAccount?.name || '---'}</p>
           </div>
           <div>
              <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1">{t.ending_balance}</p>
              <p className="text-base lg:text-lg font-black text-blue-600">{format(currentBalance)}</p>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
        <table className="w-full text-start">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{t.date}</th>
              <th className="px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{t.description}</th>
              <th className="hidden sm:table-cell px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{t.category}</th>
              <th className="px-6 lg:px-8 py-4 lg:py-5 text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest text-end">{t.amount}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredTransactions.map(tr => (
              <tr key={tr.id}>
                <td className="px-6 lg:px-8 py-4 lg:py-5 text-xs lg:text-sm font-bold text-gray-500">{tr.date}</td>
                <td className="px-6 lg:px-8 py-4 lg:py-5 text-xs lg:text-sm font-bold text-gray-800">{tr.description}</td>
                <td className="hidden sm:table-cell px-6 lg:px-8 py-4 lg:py-5 text-[10px] lg:text-xs font-bold text-blue-600">{(t.categories as any)[tr.category]}</td>
                <td className="px-6 lg:px-8 py-4 lg:py-5 text-xs lg:text-sm font-black text-gray-900 text-end">-{format(tr.amount)}</td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr><td colSpan={4} className="px-6 lg:px-8 py-10 text-center text-gray-400 font-bold italic">{t.no_transactions}</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

