const CACHE_NAME = 'finsense-v4'; // Bumped version to V4
const ASSETS = [
  '/',
  '/index.html',
  '/index.tsx',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request);
    })
  );
});

import { 
  collection, 
  addDoc, 
  query, 
  onSnapshot, 
  doc, 
  deleteDoc, 
  setDoc, 
  updateDoc,
  getDoc,
  serverTimestamp 
} from "firebase/firestore";
import { db } from "../firebase";
import { Transaction, BudgetGoal, Account, UserSettings, UserProfile } from "../types";

const cleanObject = (obj: any) => {
  const newObj = { ...obj };
  Object.keys(newObj).forEach(key => {
    if (newObj[key] === undefined) {
      delete newObj[key];
    }
  });
  return newObj;
};

export const dataService = {
  ensureUserProfile: async (userId: string, email: string) => {
    if (!userId) return;
    const userDocRef = doc(db, "users", userId);
    const userSnap = await getDoc(userDocRef);
    const baseData = { email: email || '', lastLogin: serverTimestamp(), uid: userId };

    if (!userSnap.exists()) {
      return setDoc(userDocRef, { ...baseData, name: email ? email.split('@')[0] : 'User', createdAt: serverTimestamp() });
    } else {
      const currentData = userSnap.data();
      const updates: any = { ...baseData };
      if (!currentData.name) updates.name = email ? email.split('@')[0] : 'User';
      return setDoc(userDocRef, updates, { merge: true });
    }
  },

  updateUserProfile: async (userId: string, data: Partial<UserProfile>) => {
    if (!userId) return;
    return updateDoc(doc(db, "users", userId), cleanObject(data));
  },

  subscribeToUserProfile: (userId: string, callback: (profile: UserProfile | null) => void) => {
    if (!userId) return () => {};
    return onSnapshot(doc(db, "users", userId), (doc) => {
      callback(doc.exists() ? (doc.data() as UserProfile) : null);
    });
  },

  subscribeToSettings: (userId: string, callback: (settings: UserSettings | null) => void) => {
    if (!userId) return () => {};
    return onSnapshot(doc(db, "users", userId, "config", "preferences"), (doc) => {
      callback(doc.exists() ? (doc.data() as UserSettings) : null);
    });
  },

  saveSettings: async (userId: string, settings: UserSettings) => {
    if (!userId) return;
    return setDoc(doc(db, "users", userId, "config", "preferences"), { ...cleanObject(settings), updatedAt: serverTimestamp() });
  },

  subscribe: <T>(userId: string, subCollection: string, callback: (data: T[]) => void) => {
    if (!userId) return () => {};
    const q = query(collection(db, "users", userId, subCollection));
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id })) as T[];
      callback(data);
    }, (error) => {
      console.error(`Subscription error for ${subCollection}:`, error);
    });
  },

  addTransaction: async (userId: string, transaction: Omit<Transaction, 'id' | 'userId'>) => {
    if (!userId) return;
    const { id, ...cleanTransaction } = transaction as any;
    return addDoc(collection(db, "users", userId, "history"), cleanObject({ ...cleanTransaction, userId, createdAt: serverTimestamp() }));
  },

  deleteTransaction: async (userId: string, transactionId: string) => {
    if (!userId || !transactionId) return;
    console.log(`Firestore Delete Start: history/${transactionId}`);
    try {
      const docRef = doc(db, "users", userId, "history", transactionId);
      await deleteDoc(docRef);
      console.log(`Firestore Delete Success: history/${transactionId}`);
    } catch (e) {
      console.error(`Firestore Delete Error: history/${transactionId}`, e);
      throw e;
    }
  },

  saveGoal: async (userId: string, goal: Omit<BudgetGoal, 'id' | 'userId'> & { id?: string }) => {
    if (!userId) return;
    const { id, ...data } = goal;
    const docRef = (id && id.length > 10) ? doc(db, "users", userId, "budgets", id) : doc(collection(db, "users", userId, "budgets"));
    return setDoc(docRef, { ...cleanObject(data), userId, createdAt: serverTimestamp() }, { merge: true });
  },

  deleteGoal: async (userId: string, goalId: string) => {
    if (!userId || !goalId) return;
    console.log(`Firestore Delete Start: budgets/${goalId}`);
    try {
      const docRef = doc(db, "users", userId, "budgets", goalId);
      await deleteDoc(docRef);
      console.log(`Firestore Delete Success: budgets/${goalId}`);
    } catch (e) {
      console.error(`Firestore Delete Error: budgets/${goalId}`, e);
      throw e;
    }
  },

  saveAccount: async (userId: string, account: Omit<Account, 'id' | 'userId'> & { id?: string }) => {
    if (!userId) return;
    const { id, ...data } = account;
    const docRef = (id && id.length > 10) ? doc(db, "users", userId, "accounts", id) : doc(collection(db, "users", userId, "accounts"));
    return setDoc(docRef, { ...cleanObject(data), userId, createdAt: serverTimestamp() }, { merge: true });
  },

  updateAccountBalance: async (userId: string, accountId: string, newBalance: number) => {
    if (!userId || !accountId) return;
    return updateDoc(doc(db, "users", userId, "accounts", accountId), { balance: newBalance });
  },

  deleteAccount: async (userId: string, accountId: string) => {
    if (!userId || !accountId) return;
    console.log(`Firestore Delete Start: accounts/${accountId}`);
    try {
      const docRef = doc(db, "users", userId, "accounts", accountId);
      await deleteDoc(docRef);
      console.log(`Firestore Delete Success: accounts/${accountId}`);
    } catch (e) {
      console.error(`Firestore Delete Error: accounts/${accountId}`, e);
      throw e;
    }
  }
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BudgetGoal, Currency, Account, Category, AccountType, UserSettings, UserProfile, ViewType } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AuthScreen from './components/AuthScreen';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  TrendingUp, TrendingDown, Languages, LogOut, Loader2, Globe, Trash2, Calendar, Clock, Edit2, User as UserIcon, FileText, Camera, ShieldAlert, Printer
} from 'lucide-react';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>('en');
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showForm, setShowForm] = useState(false);
  const [editingBudget, setEditingBudget] = useState<BudgetGoal | null>(null);
  const [editingAccount, setEditingAccount] = useState<Account | null>(null);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (u) => {
      if (u) {
        await dataService.ensureUserProfile(u.uid, u.email || '');
      }
      setUser(u);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const unsubProfile = dataService.subscribeToUserProfile(user.uid, (profile) => {
      setUserProfile(profile);
    });

    const unsubSettings = dataService.subscribeToSettings(user.uid, (settings) => {
      if (settings) {
        setLang(settings.language);
        setCurrency(settings.currency);
      } else {
        dataService.saveSettings(user.uid, { language: lang, currency });
      }
    });

    // Subscriptions aligned with standardized collection names
    const unsubT = dataService.subscribe(user.uid, 'history', (data: Transaction[]) => {
      setTransactions(data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    });

    const unsubG = dataService.subscribe(user.uid, 'budgets', (data: BudgetGoal[]) => {
      if (data.length === 0) {
        INITIAL_GOALS.forEach(g => dataService.saveGoal(user.uid, { ...g, userId: user.uid } as any));
      } else {
        setGoals(data);
      }
    });

    const unsubA = dataService.subscribe(user.uid, 'accounts', (data: Account[]) => {
      if (data.length === 0) {
        const defaults = [
          { name: 'Cash Wallet', type: 'Cash' as AccountType, balance: 1000 },
          { name: 'Primary Bank', type: 'Checking' as AccountType, balance: 5000 }
        ];
        defaults.forEach(acc => dataService.saveAccount(user.uid, { ...acc, userId: user.uid } as any));
      } else {
        setAccounts(data);
      }
    });

    return () => {
      unsubProfile();
      unsubSettings();
      unsubT();
      unsubG();
      unsubA();
    };
  }, [user]);

  useEffect(() => {
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [lang]);

  const updateLanguage = (newLang: Language) => {
    setLang(newLang);
    if (user) dataService.saveSettings(user.uid, { language: newLang, currency });
  };

  const updateCurrencyByCode = (code: string) => {
    const selected = CURRENCIES.find(c => c.code === code);
    if (selected) {
      setCurrency(selected);
      if (user) dataService.saveSettings(user.uid, { language: lang, currency: selected });
    }
  };

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalAssets = useMemo(() => 
    accounts
      .filter(acc => acc.type !== 'Credit Card')
      .reduce((acc, curr) => acc + curr.balance, 0), 
    [accounts]
  );

  const totalDebt = useMemo(() => 
    accounts
      .filter(acc => acc.type === 'Credit Card')
      .reduce((acc, curr) => acc + curr.balance, 0), 
    [accounts]
  );

  const totalExpenses = useMemo(() => {
    const now = new Date();
    return transactions
      .filter(tr => {
        const d = new Date(tr.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear() && !(tr as any).isSettlement;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions]);

  const userName = useMemo(() => {
    if (userProfile?.name) return userProfile.name;
    const emailStr = user?.email || '';
    if (user?.displayName) return user.displayName;
    if (emailStr.includes('@')) return emailStr.split('@')[0];
    return emailStr || 'User';
  }, [user, userProfile]);

  const handleAddTransaction = async (tData: any) => {
    if (!user) return;

    if (tData.isSettlement && tData.targetAccountId) {
      const sourceAcc = accounts.find(a => a.id === tData.accountId);
      const targetAcc = accounts.find(a => a.id === tData.targetAccountId);

      if (sourceAcc && targetAcc) {
        await dataService.updateAccountBalance(user.uid, sourceAcc.id, sourceAcc.balance - tData.amount);
        await dataService.updateAccountBalance(user.uid, targetAcc.id, targetAcc.balance - tData.amount);
      }
    } else {
      const sourceAcc = accounts.find(a => a.id === tData.accountId);
      if (sourceAcc) {
         if (sourceAcc.type === 'Credit Card') {
            await dataService.updateAccountBalance(user.uid, sourceAcc.id, sourceAcc.balance + tData.amount);
         } else {
            await dataService.updateAccountBalance(user.uid, sourceAcc.id, sourceAcc.balance - tData.amount);
         }
      }
    }

    await dataService.addTransaction(user.uid, tData);
  };

  const handleDeleteTransaction = async (id: string) => {
    const msg = lang === 'ar' ? 'هل أنت متأكد من حذف هذه المعاملة؟' : 'Are you sure you want to delete this transaction?';
    if (window.confirm(msg)) {
      try {
        await dataService.deleteTransaction(user!.uid, id);
      } catch (err: any) {
        console.error("Deletion Handler Error:", err);
        alert(`${lang === 'ar' ? 'فشل الحذف' : 'Delete failed'}: ${err.message || 'Unknown error'}`);
      }
    }
  };

  const handleDeleteGoal = async (id: string) => {
    const msg = lang === 'ar' ? 'هل أنت متأكد من حذف هذه الميزانية؟' : 'Are you sure you want to delete this budget goal?';
    if (window.confirm(msg)) {
      try {
        await dataService.deleteGoal(user!.uid, id);
      } catch (err: any) {
        console.error("Deletion Handler Error:", err);
        alert(`${lang === 'ar' ? 'فشل الحذف' : 'Delete failed'}: ${err.message || 'Unknown error'}`);
      }
    }
  };

  const handleDeleteAccount = async (id: string) => {
    const msg = lang === 'ar' ? 'هل أنت متأكد من حذف هذا الحساب؟ سيؤدي ذلك إلى فقدان بيانات الرصيد الخاصة به.' : 'Are you sure you want to delete this account? This will permanently remove its balance tracking.';
    if (window.confirm(msg)) {
      try {
        await dataService.deleteAccount(user!.uid, id);
      } catch (err: any) {
        console.error("Deletion Handler Error:", err);
        alert(`${lang === 'ar' ? 'فشل الحذف' : 'Delete failed'}: ${err.message || 'Unknown error'}`);
      }
    }
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#f8fafc]">
        <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
        <p className="text-gray-400 font-bold uppercase tracking-widest text-[10px]">Verifying Identity...</p>
      </div>
    );
  }

  if (!user) {
    return <AuthScreen lang={lang} onLanguageToggle={() => updateLanguage(lang === 'en' ? 'ar' : 'en')} />;
  }

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-[#f8fafc]" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      <nav className={`fixed ${lang === 'ar' ? 'right-0' : 'left-0'} top-0 h-full w-64 bg-white border-${lang === 'ar' ? 'l' : 'r'} border-gray-100 p-6 hidden lg:flex flex-col z-30`}>
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-black bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-700 tracking-tight">FinSense AI</span>
        </div>
        <div className="space-y-2 overflow-y-auto max-h-[70vh] custom-scrollbar pr-2">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label={t.overview} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label={t.history} active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label={t.budgets} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label={t.accounts} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
          <NavLink icon={<FileText className="w-5 h-5" />} label={t.statement} active={activeView === 'statement'} onClick={() => setActiveView('statement')} />
          <NavLink icon={<UserIcon className="w-5 h-5" />} label={t.profile} active={activeView === 'profile'} onClick={() => setActiveView('profile')} />
        </div>

        <div className="mt-auto space-y-4">
           {userProfile?.photoURL ? (
             <div className="px-5 py-2 flex items-center gap-3">
                <img src={userProfile.photoURL} alt="Profile" className="w-10 h-10 rounded-xl object-cover border border-gray-100 shadow-sm" />
                <div>
                   <p className="text-xs font-black text-gray-900 truncate max-w-[120px]">{userName}</p>
                   <p className="text-[10px] font-bold text-gray-400 truncate max-w-[120px]">{userProfile.email}</p>
                </div>
             </div>
           ) : (
              <div className="px-5 py-2 flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center text-sm font-black border border-blue-100">
                   {userName.charAt(0).toUpperCase()}
                </div>
                <div>
                   <p className="text-xs font-black text-gray-900 truncate max-w-[120px]">{userName}</p>
                   <p className="text-[10px] font-bold text-gray-400 truncate max-w-[120px]">{userProfile?.email || user.email}</p>
                </div>
              </div>
           )}

           <button onClick={() => signOut(auth)} className="w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold text-rose-500 hover:bg-rose-50 transition-all mb-4">
             <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'خروج' : 'Logout'}
           </button>

           <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100">
             <div className="flex items-center gap-2 mb-3 text-blue-600">
                <Languages className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.language}</span>
             </div>
             <div className="flex gap-1 bg-white p-1 rounded-xl shadow-sm">
                <button onClick={() => updateLanguage('en')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'en' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>EN</button>
                <button onClick={() => updateLanguage('ar')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'ar' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>AR</button>
             </div>
           </div>

           <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
             <div className="flex items-center gap-2 mb-3 text-gray-500">
                <Globe className="w-3.5 h-3.5" />
                <span className="text-[10px] font-bold uppercase tracking-wider">{t.currency}</span>
             </div>
             <select 
               value={currency.code} 
               onChange={(e) => updateCurrencyByCode(e.target.value)}
               className="bg-white border border-gray-100 text-xs font-bold text-gray-700 outline-none w-full p-2.5 rounded-xl shadow-sm cursor-pointer"
             >
               {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.label} ({c.symbol})</option>)}
             </select>
           </div>
        </div>
      </nav>

      <main className={`${lang === 'ar' ? 'lg:mr-64' : 'lg:ml-64'} p-4 lg:p-10 max-w-7xl mx-auto min-h-screen`}>
        <header className="flex justify-between items-center lg:items-start mb-6 lg:mb-10">
          <div>
            <h1 className="text-xl lg:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
              {activeView === 'dashboard' 
                ? (
                    <>
                      <span className="lg:inline hidden">{t.welcome_back}, {userName}</span>
                      <span className="lg:hidden inline">{lang === 'ar' ? 'أهلاً' : 'Hi'}, {userName}</span>
                    </>
                  )
                : (t as any)[activeView] || t.overview}
            </h1>
            <div className="hidden lg:flex items-center gap-4 mt-2 text-xs font-bold text-gray-400">
              <span className="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-full border border-gray-100 shadow-sm">
                <Calendar className="w-3.5 h-3.5 text-blue-500" />
                {currentTime.toLocaleDateString(lang, { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
              <span className="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-full border border-gray-100 shadow-sm">
                <Clock className="w-3.5 h-3.5 text-blue-500" />
                {currentTime.toLocaleTimeString(lang, { hour: '2-digit', minute: '2-digit' })}
              </span>
              <span className="text-blue-600 font-black uppercase">{currency.code}</span>
            </div>
          </div>
          <div className="flex items-center gap-2 lg:gap-3">
             <button 
                onClick={() => setActiveView('profile')} 
                className={`lg:hidden w-10 h-10 lg:w-11 lg:h-11 bg-white border border-gray-100 rounded-xl lg:rounded-2xl overflow-hidden flex items-center justify-center text-blue-600 shadow-sm active:scale-95 transition-all ${activeView === 'profile' ? 'ring-2 ring-blue-500' : ''}`}
             >
                {userProfile?.photoURL ? (
                  <img src={userProfile.photoURL} alt="Profile" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-sm font-black">{userName.charAt(0).toUpperCase()}</span>
                )}
             </button>
             <button onClick={() => setShowForm(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 lg:px-6 py-2.5 lg:py-3.5 rounded-xl lg:rounded-2xl font-black shadow-lg lg:shadow-xl shadow-blue-100 active:scale-95 transition-all text-[10px] lg:text-sm">
               <Plus className="w-3.5 h-3.5 lg:w-5 lg:h-5" /> <span className="uppercase tracking-widest">{t.entry}</span>
             </button>
          </div>
        </header>

        {activeView === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 lg:gap-6 mb-8 lg:mb-10">
              <StatCard 
                title={t.total_assets} 
                value={formatMoney(totalAssets)} 
                trend={t.trend_liquid} 
                trendType="up" 
                icon={<TrendingUp className="w-4 h-4 lg:w-5 lg:h-5" />} 
                lang={lang} 
                onClick={() => setActiveView('accounts')}
              />
              <StatCard 
                title={t.total_expenses} 
                value={formatMoney(totalExpenses)} 
                trend={t.trend_monthly} 
                trendType="down" 
                icon={<TrendingDown className="w-4 h-4 lg:w-5 lg:h-5 text-amber-500" />} 
                lang={lang} 
                onClick={() => setActiveView('history')}
              />
              <StatCard 
                title={t.total_debt} 
                value={formatMoney(totalDebt)} 
                trend={t.trend_debt} 
                trendType="down" 
                icon={<ShieldAlert className="w-4 h-4 lg:w-5 lg:h-5 text-rose-500" />} 
                lang={lang} 
                isDebt 
                onClick={() => setActiveView('accounts')}
              />
              <StatCard 
                title={t.budget_health} 
                value={`${goals.length}`} 
                trend={t.trend_goals} 
                trendType="up" 
                icon={<Target className="w-4 h-4 lg:w-5 lg:h-5" />} 
                lang={lang} 
                onClick={() => setActiveView('budgets')}
              />
            </div>
            <div className="space-y-6 lg:space-y-8">
              <Charts transactions={transactions} lang={lang} />
            </div>
          </div>
        )}
        {activeView === 'history' && <TransactionList transactions={transactions} onDelete={handleDeleteTransaction} lang={lang} />}
        {activeView === 'budgets' && (
          <BudgetsView 
            user={user} 
            goals={goals} 
            transactions={transactions} 
            formatMoney={formatMoney} 
            lang={lang} 
            onAddClick={() => { setEditingBudget(null); setShowBudgetForm(true); }} 
            onEditClick={(goal: BudgetGoal) => { setEditingBudget(goal); setShowBudgetForm(true); }}
            onDelete={handleDeleteGoal}
          />
        )}
        {activeView === 'accounts' && (
          <AccountsView 
            user={user} 
            accounts={accounts} 
            formatMoney={formatMoney} 
            lang={lang} 
            onAddClick={() => { setEditingAccount(null); setShowAccountForm(true); }} 
            onEditClick={(acc: Account) => { setEditingAccount(acc); setShowAccountForm(true); }}
            onDelete={handleDeleteAccount}
          />
        )}
        {activeView === 'profile' && (
          <ProfileView 
            profile={userProfile} 
            lang={lang} 
            updateLanguage={updateLanguage}
            currency={currency}
            updateCurrencyByCode={updateCurrencyByCode}
            transactionsCount={transactions.length} 
            accountsCount={accounts.length} 
          />
        )}
        {activeView === 'statement' && <StatementView accounts={accounts} transactions={transactions} currency={currency} lang={lang} />}
      </main>

      {/* Mobile Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-100 px-2 py-4 flex justify-around items-center lg:hidden z-40 shadow-[0_-10px_40px_rgba(0,0,0,0.03)] rounded-t-[2.5rem]">
        <MobileNavLink icon={<LayoutDashboard className="w-5 h-5" />} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
        <MobileNavLink icon={<History className="w-5 h-5" />} active={activeView === 'history'} onClick={() => setActiveView('history')} />
        <MobileNavLink icon={<Target className="w-5 h-5" />} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
        <button onClick={() => setShowForm(true)} className="w-12 h-12 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center -translate-y-8 active:scale-90 transition-transform"><Plus className="w-6 h-6" /></button>
        <MobileNavLink icon={<CreditCard className="w-5 h-5" />} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
        <MobileNavLink icon={<FileText className="w-5 h-5" />} active={activeView === 'statement'} onClick={() => setActiveView('statement')} />
        <MobileNavLink icon={<UserIcon className="w-5 h-5" />} active={activeView === 'profile'} onClick={() => setActiveView('profile')} />
      </nav>

      {showForm && <TransactionForm accounts={accounts} onAdd={handleAddTransaction} onClose={() => setShowForm(false)} lang={lang} />}
      {showBudgetForm && <BudgetForm initialData={editingBudget} onAdd={(b: any) => dataService.saveGoal(user!.uid, b)} onClose={() => { setShowBudgetForm(false); setEditingBudget(null); }} lang={lang} />}
      {showAccountForm && <AccountForm initialData={editingAccount} onAdd={(a: any) => dataService.saveAccount(user!.uid, a)} onClose={() => { setShowAccountForm(false); setEditingAccount(null); }} lang={lang} />}
    </div>
  );
};

const ProfileView = ({ profile, lang, updateLanguage, currency, updateCurrencyByCode, transactionsCount, accountsCount }: { 
  profile: UserProfile | null, 
  lang: Language, 
  updateLanguage: (l: Language) => void,
  currency: Currency,
  updateCurrencyByCode: (c: string) => void,
  transactionsCount: number, 
  accountsCount: number 
}) => {
  const t = translations[lang];
  const [name, setName] = useState(profile?.name || '');
  const [photoURL, setPhotoURL] = useState(profile?.photoURL || '');
  const [loading, setLoading] = useState(false);
  const [photoLoading, setPhotoLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (profile?.name) setName(profile.name);
    if (profile?.photoURL) setPhotoURL(profile.photoURL);
  }, [profile]);

  const compressImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_DIM = 200;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_DIM) {
            height *= MAX_DIM / width;
            width = MAX_DIM;
          }
        } else {
          if (height > MAX_DIM) {
            width *= MAX_DIM / height;
            height = MAX_DIM;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return resolve(base64Str);
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.4)); 
      };
      img.onerror = () => resolve(base64Str);
    });
  };

  const handleUpdate = async () => {
    if (!profile?.uid) return;
    setLoading(true);
    try {
      await dataService.updateUserProfile(profile.uid, { name, photoURL });
    } finally {
      setLoading(false);
    }
  };

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && profile?.uid) {
      setPhotoLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        const compressed = await compressImage(base64);
        setPhotoURL(compressed);
        try {
          await dataService.updateUserProfile(profile.uid, { photoURL: compressed });
        } catch (err) {
          console.error("Auto-save failed:", err);
        } finally {
          setPhotoLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const initialChar = (profile?.name || profile?.email || 'U').charAt(0).toUpperCase();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl space-y-6 lg:space-y-8">
      <div className="bg-white p-6 lg:p-8 rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm">
        <div className="flex items-center gap-6 mb-10">
          <div className="relative group cursor-pointer" onClick={handleImageClick}>
            <div className="w-20 h-20 lg:w-24 lg:h-24 bg-blue-100 text-blue-600 rounded-3xl lg:rounded-[2.5rem] flex items-center justify-center text-3xl font-black overflow-hidden border-2 border-white shadow-xl shadow-blue-50 transition-transform group-hover:scale-105">
              {photoLoading ? (
                <div className="flex flex-col items-center justify-center">
                  <Loader2 className="w-6 h-6 animate-spin mb-1" />
                  <span className="text-[8px] font-black uppercase">Saving</span>
                </div>
              ) : photoURL ? (
                <img src={photoURL} alt="Avatar" className="w-full h-full object-cover" />
              ) : (
                initialChar
              )}
            </div>
            <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-2 rounded-xl shadow-lg border-2 border-white transition-transform group-hover:scale-110 pointer-events-none">
              <Camera className="w-4 h-4" />
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileChange}
              onClick={(e) => (e.target as HTMLInputElement).value = ''}
            />
          </div>
          <div>
            <h2 className="text-xl lg:text-2xl font-black text-gray-900">{profile?.name || 'User'}</h2>
            <p className="text-gray-400 font-bold text-xs lg:text-sm">{profile?.email}</p>
          </div>
        </div>

        <div className="space-y-6">
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.full_name}</label>
            <input 
              type="text" 
              value={name} 
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-gray-50 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-800 focus:bg-white focus:border-blue-100 transition-colors text-sm"
            />
          </div>
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">{t.email_address}</label>
            <input 
              disabled
              type="text" 
              value={profile?.email || ''} 
              className="w-full bg-gray-100 border border-gray-100 p-4 rounded-2xl outline-none font-bold text-gray-400 cursor-not-allowed text-sm"
            />
          </div>
          <button 
            onClick={handleUpdate}
            disabled={loading || (name === profile?.name && photoURL === profile?.photoURL)}
            className="w-full bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white p-4 lg:p-5 rounded-2xl font-black shadow-xl shadow-blue-100 transition-all active:scale-95 uppercase tracking-widest text-[10px] lg:text-xs"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : t.update_profile}
          </button>
        </div>

        <div className="grid grid-cols-2 gap-4 mt-8 lg:mt-10 pt-8 lg:pt-10 border-t border-gray-50">
           <div className="text-center">
              <p className="text-xl lg:text-2xl font-black text-gray-900">{transactionsCount}</p>
              <p className="text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.history}</p>
           </div>
           <div className="text-center">
              <p className="text-xl lg:text-2xl font-black text-gray-900">{accountsCount}</p>
              <p className="text-[9px] lg:text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.accounts}</p>
           </div>
        </div>
      </div>

      <div className="bg-white p-6 lg:p-8 rounded-3xl lg:rounded-[2.5rem] border border-gray-100 shadow-sm space-y-6 lg:space-y-8">
        <div>
