                  {formatMoney(acc.balance)}
                </p>
                {isSurplus && (
                  <div className="mt-2 inline-flex items-center gap-1.5 bg-emerald-500/20 px-2 py-1 rounded-lg border border-emerald-500/30">
                    <TrendingUp className="w-3 h-3 text-emerald-400" />
                    <span className="text-[8px] lg:text-[10px] font-black uppercase text-emerald-300">
                      {tStr.surplus}: {formatMoney(acc.balance - limit)}
                    </span>
                  </div>
                )}
              </div>

              {isDebt && limit > 0 && (
                <div className="space-y-2 lg:space-y-3 relative z-10">
                   <div className="flex justify-between text-[7px] lg:text-[10px] font-black uppercase opacity-70">
                      <span className="line-clamp-1">{isSurplus ? '100%' : `${usedPercent.toFixed(0)}%`} {tStr.used}</span>
