                      <div className={`h-full transition-all duration-1000 ${isSurplus ? 'bg-emerald-400' : 'bg-white'}`} style={{ width: `${isSurplus ? 100 : usedPercent}%` }} />
                   </div>
                   <p className="text-[6px] lg:text-[10px] font-black uppercase opacity-50 line-clamp-1">{tStr.limit}: {formatMoney(limit)}</p>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

