import React from 'react';
import { AlertCircle, X } from 'lucide-react';
import { Language, translations } from '../translations';

interface Props {
  lang: Language;
  title?: string;
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
  confirmText?: string;
  isDanger?: boolean;
}

const ConfirmModal: React.FC<Props> = ({ 
  lang, 
  title, 
  message, 
  onConfirm, 
  onCancel, 
  confirmText,
  isDanger = true 
}) => {
  const t = translations[lang];

  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-[200] p-4 animate-in fade-in duration-200" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      <div className="bg-white rounded-[2.5rem] p-8 lg:p-10 w-full max-w-sm shadow-2xl animate-in zoom-in-95 duration-300 relative overflow-hidden">
        <button 
          onClick={onCancel} 
          className="absolute top-6 right-6 p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        <div className={`w-16 h-16 rounded-3xl flex items-center justify-center mb-6 ${isDanger ? 'bg-rose-50 text-rose-500' : 'bg-blue-50 text-blue-600'}`}>
          <AlertCircle className="w-8 h-8" />
        </div>

        <h2 className="text-xl lg:text-2xl font-black text-gray-900 mb-2">
          {title || (lang === 'ar' ? 'هل أنت متأكد؟' : 'Are you sure?')}
        </h2>
        <p className="text-sm font-bold text-gray-500 mb-8 leading-relaxed">
          {message}
        </p>

        <div className="flex gap-4">
          <button 
            onClick={onCancel} 
            className="flex-1 py-4 rounded-2xl font-bold text-gray-400 hover:bg-gray-50 transition-colors uppercase tracking-widest text-[10px]"
          >
            {t.cancel}
          </button>
          <button 
            onClick={onConfirm} 
            className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all active:scale-95 uppercase tracking-widest text-[10px] ${isDanger ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
          >
            {confirmText || t.delete}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ConfirmModal;

import React from 'react';
import { Transaction } from '../types';
import { CATEGORY_ICONS } from '../constants';
import { Smile, Frown, Meh, Zap, Moon, Clock, Trash2, Edit2 } from 'lucide-react';
import { Language, translations } from '../translations';

interface Props {
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onEdit?: (transaction: Transaction) => void;
  lang: Language;
}

const MoodIcon = ({ mood }: { mood: string }) => {
  switch (mood) {
    case 'Happy': return <Smile className="w-4 h-4 text-green-500" />;
    case 'Stressed': return <Zap className="w-4 h-4 text-orange-500" />;
    case 'Tired': return <Moon className="w-4 h-4 text-blue-500" />;
    case 'Bored': return <Meh className="w-4 h-4 text-gray-400" />;
    case 'Excited': return <Zap className="w-4 h-4 text-yellow-500" />;
    default: return <Smile className="w-4 h-4 text-gray-300" />;
  }
};

const TransactionList: React.FC<Props> = ({ transactions, onDelete, onEdit, lang }) => {
  const tStrings = translations[lang];

  if (transactions.length === 0) {
    return (
      <div className="text-center py-12 bg-white rounded-[2.5rem] border border-dashed border-gray-200">
        <p className="text-gray-400 font-bold italic">{tStrings.no_transactions}</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="overflow-x-auto custom-scrollbar">
        <table className="w-full text-start border-collapse">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{tStrings.description}</th>
              <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{tStrings.category}</th>
              <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{tStrings.date}</th>
              <th className="hidden lg:table-cell px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-start">{tStrings.emotional_context}</th>
              <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-end">{tStrings.amount}</th>
              <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {transactions.map((t) => (
              <tr key={t.id} className="hover:bg-blue-50/30 transition-colors group">
                <td className="px-8 py-5">
                  <span className="text-sm font-bold text-gray-800 line-clamp-1">{t.description || (lang === 'ar' ? 'بدون وصف' : 'No description')}</span>
                </td>
                <td className="px-8 py-5">
                  <div className="flex items-center gap-2">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-xl shrink-0">
                      {CATEGORY_ICONS[t.category]}
                    </div>
                    <span className="text-[10px] font-black uppercase text-gray-500 tracking-wider">{(tStrings.categories as any)[t.category]}</span>
                  </div>
                </td>
                <td className="px-8 py-5">
                  <div className="flex items-center gap-2 text-xs font-bold text-gray-400">
                    <Clock className="w-3.5 h-3.5 text-blue-500" />
                    <span className="whitespace-nowrap">{t.date}</span>
                  </div>
                </td>
                <td className="hidden lg:table-cell px-8 py-5">
                  <div className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 rounded-full w-fit">
                    <MoodIcon mood={t.mood} />
                    <span className="text-[10px] font-black uppercase text-gray-500">{(tStrings.moods as any)[t.mood]}</span>
                  </div>
                </td>
                <td className="px-8 py-5 text-end">
                  <span className="text-sm font-black text-gray-900">{t.amount.toFixed(2)}</span>
                </td>
                <td className="px-8 py-5 text-center">
                  <div className="flex items-center justify-center gap-1">
                    {onEdit && (
                      <button 
                        type="button"
                        onClick={() => onEdit(t)}
                        className="p-3 text-gray-300 hover:text-blue-500 hover:bg-blue-50 rounded-xl transition-all active:scale-90"
                        title={lang === 'ar' ? 'تعديل' : 'Edit'}
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                    )}
                    <button 
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onDelete(t.id);
                      }}
                      className="p-3 text-gray-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all active:scale-90"
                      title={tStrings.delete}
                      aria-label={tStrings.delete}
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default TransactionList;

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORIES, MOODS } from '../constants';
import { Transaction, Category, Mood, Account } from '../types';
import { PlusCircle, X, ArrowDownRight, RefreshCw } from 'lucide-react';
import { Language, translations } from '../translations';

interface Props {
  accounts: Account[];
  initialData?: Transaction | null;
  onAdd: (t: Omit<Transaction, 'userId'> & { isSettlement?: boolean, targetAccountId?: string }) => void;
  onUpdate?: (id: string, t: Partial<Transaction>) => void;
  onClose: () => void;
  lang: Language;
}

const TransactionForm: React.FC<Props> = ({ accounts, initialData, onAdd, onUpdate, onClose, lang }) => {
  const t = translations[lang];
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [category, setCategory] = useState<Category>(initialData?.category || CATEGORIES[0]);
  const [description, setDescription] = useState(initialData?.description || '');
  const [mood, setMood] = useState<Mood>(initialData?.mood || 'Neutral');
  const [accountId, setAccountId] = useState(initialData?.accountId || accounts[0]?.id || '');
  const [targetAccountId, setTargetAccountId] = useState(initialData?.targetAccountId || '');
  const [isSettlement, setIsSettlement] = useState(initialData?.isSettlement || false);
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [time, setTime] = useState(initialData?.time || new Date().toTimeString().slice(0, 5));

  const creditCardAccounts = useMemo(() => accounts.filter(a => a.type === 'Credit Card'), [accounts]);
  const fundingAccounts = useMemo(() => accounts.filter(a => a.type !== 'Credit Card'), [accounts]);

  const isEditing = !!initialData;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || isNaN(Number(amount))) return;
    if (isSettlement && !targetAccountId) return;

    const transactionData: any = {
      amount: Number(amount),
      category: isSettlement ? 'Settlement' : category,
      description: isSettlement ? `${t.is_settlement}: ${description.replace(t.is_settlement + ': ', '')}` : description,
      mood,
      date,
      time,
      accountId,
      isSettlement,
      targetAccountId: isSettlement ? targetAccountId : null,
    };

    if (isEditing && onUpdate && initialData?.id) {
      onUpdate(initialData.id, transactionData);
    } else {
      onAdd({
        ...transactionData,
        id: Math.random().toString(36).substr(2, 9),
      });
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
          <h2 className="text-xl font-bold text-gray-800">
            {isEditing ? (lang === 'ar' ? 'تعديل المعاملة' : 'Edit Transaction') : t.log_transaction}
          </h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4 max-h-[80vh] overflow-y-auto custom-scrollbar">
          <div className="flex items-center justify-between p-4 bg-blue-50/50 rounded-2xl border border-blue-100 mb-2">
            <div className="flex items-center gap-3">
               <ArrowDownRight className="w-5 h-5 text-blue-600" />
               <span className="text-sm font-bold text-blue-900">{t.is_settlement}</span>
            </div>
            <button 
              type="button"
              onClick={() => {
                const nextState = !isSettlement;
                setIsSettlement(nextState);
                if (nextState) {
                  const firstFund = fundingAccounts[0]?.id;
                  if (firstFund) setAccountId(firstFund);
                  const firstCC = creditCardAccounts[0]?.id;
                  if (firstCC) setTargetAccountId(firstCC);
                }
              }}
              className={`w-12 h-6 rounded-full transition-all relative ${isSettlement ? 'bg-blue-600' : 'bg-gray-200'}`}
            >
              <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${lang === 'ar' ? (isSettlement ? 'right-7' : 'right-1') : (isSettlement ? 'left-7' : 'left-1')}`} />
            </button>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">{t.amount}</label>
            <input
              required
              type="number"
              step="0.01"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              className="w-full px-4 py-4 text-2xl font-bold border border-gray-100 bg-gray-50 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              placeholder="0.00"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">{t.source_account}</label>
            <select
              value={accountId}
              onChange={(e) => setAccountId(e.target.value)}
              className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm outline-none font-bold text-gray-700"
            >
              {(isSettlement ? fundingAccounts : accounts).map(acc => (
                <option key={acc.id} value={acc.id}>{acc.name} ({acc.balance.toLocaleString()})</option>
              ))}
            </select>
          </div>

          {isSettlement && (
            <div className="animate-in slide-in-from-top-2">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">{t.target_credit_card}</label>
              <select
                required
                value={targetAccountId}
                onChange={(e) => setTargetAccountId(e.target.value)}
                className="w-full px-4 py-3 bg-emerald-50 border border-emerald-100 rounded-xl text-sm outline-none font-bold text-emerald-700"
              >
                <option value="" disabled>Select Credit Card</option>
                {creditCardAccounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name} (Available: {acc.balance.toLocaleString()})</option>)}
              </select>
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
            <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
          </div>

          {!isSettlement && (
            <select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold">
              {CATEGORIES.filter(c => c !== 'Settlement').map(c => <option key={c} value={c}>{(t.categories as any)[c]}</option>)}
            </select>
          )}

          <div className="flex flex-wrap gap-2">
            {MOODS.map(m => (
              <button key={m} type="button" onClick={() => setMood(m)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95 ${mood === m ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}>{(t.moods as any)[m]}</button>
            ))}
          </div>

          <input 
            type="text" 
            value={description} 
            onChange={e => setDescription(e.target.value)} 
            className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500/20" 
            placeholder={t.description} 
          />

          <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-100 uppercase tracking-widest text-xs transition-all active:scale-95 flex items-center justify-center gap-2">
            {isEditing ? <RefreshCw className="w-5 h-5" /> : <PlusCircle className="w-5 h-5" />}
            {isEditing ? (lang === 'ar' ? 'تحديث' : 'Update') : (lang === 'ar' ? 'إضافة' : 'Add')}
          </button>
        </form>
      </div>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { onAuthStateChanged, User, signOut } from 'firebase/auth';
import { auth } from './firebase';
import { dataService } from './services/dataService';
import { Transaction, BudgetGoal, Currency, Account, Category, AccountType, UserSettings, UserProfile, ViewType } from './types';
import { INITIAL_GOALS, CATEGORY_ICONS, CURRENCIES, CATEGORIES } from './constants';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Charts from './components/Charts';
import AuthScreen from './components/AuthScreen';
import ConfirmModal from './components/ConfirmModal';
import { Language, translations } from './translations';
import { 
  Wallet, Plus, LayoutDashboard, History, Target, CreditCard, 
  TrendingUp, TrendingDown, Languages, LogOut, Loader2, Globe, Trash2, Calendar, Clock, Edit2, User as UserIcon, FileText, Camera, ShieldAlert, Printer
} from 'lucide-react';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [user, setUser] = useState<User | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [lang, setLang] = useState<Language>('en');
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showForm, setShowForm] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [confirmDeleteType, setConfirmDeleteType] = useState<'transaction' | 'budget' | 'account' | null>(null);

  const [editingBudget, setEditingBudget] = useState<BudgetGoal | null>(null);
  const [editingAccount, setEditingAccount] = useState<Account | null>(null);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [showAccountForm, setShowAccountForm] = useState(false);

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [goals, setGoals] = useState<BudgetGoal[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (u) => {
      if (u) {
        await dataService.ensureUserProfile(u.uid, u.email || '');
      }
      setUser(u);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const unsubProfile = dataService.subscribeToUserProfile(user.uid, (profile) => {
      setUserProfile(profile);
    });

    const unsubSettings = dataService.subscribeToSettings(user.uid, (settings) => {
      if (settings) {
        setLang(settings.language);
        setCurrency(settings.currency);
      } else {
        dataService.saveSettings(user.uid, { language: lang, currency });
      }
    });

    const unsubT = dataService.subscribe(user.uid, 'transactions', (data: Transaction[]) => {
      setTransactions(data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
    });

    const unsubG = dataService.subscribe(user.uid, 'budgets', (data: BudgetGoal[]) => {
      setGoals(data);
    });

    const unsubA = dataService.subscribe(user.uid, 'accounts', (data: Account[]) => {
      setAccounts(data);
    });

    return () => {
      unsubProfile();
      unsubSettings();
      unsubT();
      unsubG();
      unsubA();
    };
  }, [user]);

  useEffect(() => {
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [lang]);

  const updateLanguage = (newLang: Language) => {
    setLang(newLang);
    if (user) dataService.saveSettings(user.uid, { language: newLang, currency });
  };

  const updateCurrencyByCode = (code: string) => {
    const selected = CURRENCIES.find(c => c.code === code);
    if (selected) {
      setCurrency(selected);
      if (user) dataService.saveSettings(user.uid, { language: lang, currency: selected });
    }
  };

  const t = translations[lang];

  const formatMoney = (amount: number) => {
    return `${currency.symbol} ${amount.toLocaleString(lang, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const totalAssets = useMemo(() => 
    accounts
      .filter(acc => acc.type !== 'Credit Card')
      .reduce((acc, curr) => acc + curr.balance, 0), 
    [accounts]
  );

  const totalDebt = useMemo(() => 
    accounts
      .filter(acc => acc.type === 'Credit Card')
      .reduce((acc, curr) => {
        const limit = curr.creditLimit || 0;
        return acc + Math.max(0, limit - curr.balance);
      }, 0), 
    [accounts]
  );

  const totalExpenses = useMemo(() => {
    const now = new Date();
    return transactions
      .filter(tr => {
        const d = new Date(tr.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear() && !tr.isSettlement;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions]);

  const userName = useMemo(() => {
    if (userProfile?.name) return userProfile.name;
    const emailStr = user?.email || '';
    if (user?.displayName) return user.displayName;
    if (emailStr.includes('@')) return emailStr.split('@')[0];
    return emailStr || 'User';
  }, [user, userProfile]);

  const handleAddTransaction = async (tData: any) => {
    if (!user) return;

    if (tData.isSettlement && tData.targetAccountId) {
      const sourceAcc = accounts.find(a => a.id === tData.accountId);
      const targetAcc = accounts.find(a => a.id === tData.targetAccountId);
      if (sourceAcc && targetAcc) {
        await dataService.updateAccountBalance(user.uid, sourceAcc.id, sourceAcc.balance - tData.amount);
        await dataService.updateAccountBalance(user.uid, targetAcc.id, targetAcc.balance + tData.amount);
      }
    } else {
      const sourceAcc = accounts.find(a => a.id === tData.accountId);
      if (sourceAcc) {
         await dataService.updateAccountBalance(user.uid, sourceAcc.id, sourceAcc.balance - tData.amount);
      }
    }
    await dataService.addTransaction(user.uid, tData);
  };

  const handleUpdateTransaction = async (id: string, newData: any) => {
    if (!user) return;
    const oldT = transactions.find(t => t.id === id);
    if (!oldT) return;

    // 1. Reverse old impact
    if (oldT.isSettlement && oldT.targetAccountId) {
      const oldSource = accounts.find(a => a.id === oldT.accountId);
      const oldTarget = accounts.find(a => a.id === oldT.targetAccountId);
      if (oldSource) await dataService.updateAccountBalance(user.uid, oldSource.id, oldSource.balance + oldT.amount);
      if (oldTarget) await dataService.updateAccountBalance(user.uid, oldTarget.id, oldTarget.balance - oldT.amount);
    } else {
      const oldSource = accounts.find(a => a.id === oldT.accountId);
      if (oldSource) await dataService.updateAccountBalance(user.uid, oldSource.id, oldSource.balance + oldT.amount);
    }

    // 2. Refresh local accounts (Wait for state update or find them in current state)
    // To be safe, we re-fetch balances from the updated objects or calculate based on the new accounts state
    const currentAccounts = accounts; // This might be slightly stale but within the same cycle it should be okay if we chain correctly

    // 3. Apply new impact
    if (newData.isSettlement && newData.targetAccountId) {
      const newSource = currentAccounts.find(a => a.id === newData.accountId);
      const newTarget = currentAccounts.find(a => a.id === newData.targetAccountId);
      if (newSource) await dataService.updateAccountBalance(user.uid, newSource.id, newSource.balance - newData.amount + (oldT.accountId === newData.accountId ? oldT.amount : 0));
      if (newTarget) await dataService.updateAccountBalance(user.uid, newTarget.id, newTarget.balance + newData.amount - (oldT.targetAccountId === newData.targetAccountId ? oldT.amount : 0));
    } else {
      const newSource = currentAccounts.find(a => a.id === newData.accountId);
      if (newSource) await dataService.updateAccountBalance(user.uid, newSource.id, newSource.balance - newData.amount + (oldT.accountId === newData.accountId ? oldT.amount : 0));
    }

    await dataService.updateTransaction(user.uid, id, newData);
  };

  const handleConfirmDelete = async () => {
    if (!user || !confirmDeleteId || !confirmDeleteType) return;

    if (confirmDeleteType === 'transaction') {
      const t = transactions.find(x => x.id === confirmDeleteId);
      if (t) {
        // Reverse balance impact before delete
        if (t.isSettlement && t.targetAccountId) {
          const s = accounts.find(a => a.id === t.accountId);
          const tr = accounts.find(a => a.id === t.targetAccountId);
          if (s) await dataService.updateAccountBalance(user.uid, s.id, s.balance + t.amount);
          if (tr) await dataService.updateAccountBalance(user.uid, tr.id, tr.balance - t.amount);
        } else {
          const s = accounts.find(a => a.id === t.accountId);
          if (s) await dataService.updateAccountBalance(user.uid, s.id, s.balance + t.amount);
        }
        await dataService.deleteTransaction(user.uid, confirmDeleteId);
      }
    } else if (confirmDeleteType === 'budget') {
      await dataService.deleteGoal(user.uid, confirmDeleteId);
    } else if (confirmDeleteType === 'account') {
      await dataService.deleteAccount(user.uid, confirmDeleteId);
    }

    setConfirmDeleteId(null);
    setConfirmDeleteType(null);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-[#f8fafc]" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      <nav className={`fixed ${lang === 'ar' ? 'right-0' : 'left-0'} top-0 h-full w-64 bg-white border-${lang === 'ar' ? 'l' : 'r'} border-gray-100 p-6 hidden lg:flex flex-col z-30`}>
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100">
            <Wallet className="w-6 h-6" />
          </div>
          <span className="text-xl font-black bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-700 tracking-tight">FinSense</span>
        </div>
        <div className="space-y-2 overflow-y-auto max-h-[70vh] custom-scrollbar pr-2">
          <NavLink icon={<LayoutDashboard className="w-5 h-5" />} label={t.overview} active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavLink icon={<History className="w-5 h-5" />} label={t.history} active={activeView === 'history'} onClick={() => setActiveView('history')} />
          <NavLink icon={<Target className="w-5 h-5" />} label={t.budgets} active={activeView === 'budgets'} onClick={() => setActiveView('budgets')} />
          <NavLink icon={<CreditCard className="w-5 h-5" />} label={t.accounts} active={activeView === 'accounts'} onClick={() => setActiveView('accounts')} />
          <NavLink icon={<FileText className="w-5 h-5" />} label={t.statement} active={activeView === 'statement'} onClick={() => setActiveView('statement')} />
          <NavLink icon={<UserIcon className="w-5 h-5" />} label={t.profile} active={activeView === 'profile'} onClick={() => setActiveView('profile')} />
        </div>

        <div className="mt-auto space-y-4">
           <button onClick={() => signOut(auth)} className="w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl text-sm font-bold text-rose-500 hover:bg-rose-50 transition-all mb-4">
             <LogOut className="w-5 h-5" /> {lang === 'ar' ? 'خروج' : 'Logout'}
           </button>
           {/* Language & Currency toggles */}
           <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100">
             <div className="flex gap-1 bg-white p-1 rounded-xl shadow-sm">
                <button onClick={() => updateLanguage('en')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'en' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>EN</button>
                <button onClick={() => updateLanguage('ar')} className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${lang === 'ar' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>AR</button>
             </div>
           </div>
        </div>
      </nav>

      <main className={`${lang === 'ar' ? 'lg:mr-64' : 'lg:ml-64'} p-4 lg:p-10 max-w-7xl mx-auto min-h-screen`}>
        <header className="flex justify-between items-center lg:items-start mb-6 lg:mb-10">
          <div>
            <h1 className="text-xl lg:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
              {(t as any)[activeView] || t.overview}
            </h1>
          </div>
          <div className="flex items-center gap-2 lg:gap-3">
             <button onClick={() => { setEditingTransaction(null); setShowForm(true); }} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 lg:px-6 py-2.5 lg:py-3.5 rounded-xl lg:rounded-2xl font-black shadow-lg lg:shadow-xl shadow-blue-100 active:scale-95 transition-all text-[10px] lg:text-sm">
               <Plus className="w-3.5 h-3.5 lg:w-5 lg:h-5" /> <span className="uppercase tracking-widest">{t.entry}</span>
             </button>
          </div>
        </header>

        {activeView === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 lg:gap-6 mb-8 lg:mb-10">
              <StatCard title={t.total_assets} value={formatMoney(totalAssets)} trend={t.trend_liquid} trendType="up" icon={<TrendingUp className="w-4 h-4 lg:w-5 lg:h-5" />} lang={lang} onClick={() => setActiveView('accounts')} />
              <StatCard title={t.total_expenses} value={formatMoney(totalExpenses)} trend={t.trend_monthly} trendType="down" icon={<TrendingDown className="w-4 h-4 lg:w-5 lg:h-5 text-amber-500" />} lang={lang} onClick={() => setActiveView('history')} />
              <StatCard title={t.total_debt} value={formatMoney(totalDebt)} trend={t.trend_debt} trendType="down" icon={<ShieldAlert className="w-4 h-4 lg:w-5 lg:h-5 text-rose-500" />} lang={lang} isDebt onClick={() => setActiveView('accounts')} />
              <StatCard title={t.budget_health} value={`${goals.length}`} trend={t.trend_goals} trendType="up" icon={<Target className="w-4 h-4 lg:w-5 lg:h-5" />} lang={lang} onClick={() => setActiveView('budgets')} />
            </div>
            <Charts transactions={transactions} lang={lang} />
          </div>
        )}

        {activeView === 'history' && (
          <TransactionList 
            transactions={transactions} 
            onDelete={(id) => { setConfirmDeleteId(id); setConfirmDeleteType('transaction'); }} 
            onEdit={(t) => { setEditingTransaction(t); setShowForm(true); }}
            lang={lang} 
          />
        )}

        {activeView === 'budgets' && (
          <BudgetsView 
            goals={goals} 
            transactions={transactions} 
            formatMoney={formatMoney} 
            lang={lang} 
            onAddClick={() => { setEditingBudget(null); setShowBudgetForm(true); }} 
            onEditClick={(goal: BudgetGoal) => { setEditingBudget(goal); setShowBudgetForm(true); }}
            onDelete={(id: string) => { setConfirmDeleteId(id); setConfirmDeleteType('budget'); }}
          />
        )}

        {activeView === 'accounts' && (
          <AccountsView 
            accounts={accounts} 
            formatMoney={formatMoney} 
            lang={lang} 
            onAddClick={() => { setEditingAccount(null); setShowAccountForm(true); }} 
            onEditClick={(acc: Account) => { setEditingAccount(acc); setShowAccountForm(true); }}
            onDelete={(id: string) => { setConfirmDeleteId(id); setConfirmDeleteType('account'); }}
          />
        )}

