                <button onClick={() => onDelete(acc.id)} className="p-1.5 text-white/40 hover:text-rose-300 transition-colors" title={lang === 'ar' ? 'حذف' : 'Delete'}><Trash2 className="w-3 lg:w-5 h-3 lg:h-5" /></button>
