              <div className="w-full h-1.5 lg:h-3 bg-gray-50 rounded-full overflow-hidden mb-2 lg:mb-3"><div className={`h-full transition-all duration-1000 ${percent > 90 ? 'bg-rose-500' : 'bg-blue-600'}`} style={{width: `${percent}%`}} /></div>
