    <div className={`p-2 lg:p-4 rounded-xl lg:rounded-3xl ${isDebt ? 'bg-rose-50 text-rose-500' : 'bg-gray-50 group-hover:bg-blue-50 group-hover:text-blue-600 transition-colors'}`}>{icon}</div>
