    </div>
  );
};

const StatementView = ({ profile, accounts, transactions, currency, lang, onDelete }: { profile: UserProfile | null, accounts: Account[], transactions: Transaction[], currency: Currency, lang: Language, onDelete: (id: string) => void }) => {
  const t = translations[lang];
  const [selectedAccountId, setSelectedAccountId] = useState(accounts[0]?.id || '');
  const [period, setPeriod] = useState<'current' | 'last' | 'custom'>('current');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const filteredTransactions = useMemo(() => {
    if (!selectedAccountId) return [];
    let list = transactions.filter(tr => tr.accountId === selectedAccountId);
    const now = new Date();
    if (period === 'current') list = list.filter(tr => { const d = new Date(tr.date); return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear(); });
    else if (period === 'last') { const lm = new Date(now.getFullYear(), now.getMonth() - 1); list = list.filter(tr => { const d = new Date(tr.date); return d.getMonth() === lm.getMonth() && d.getFullYear() === lm.getFullYear(); }); }
    else if (period === 'custom') { if (dateFrom) list = list.filter(tr => new Date(tr.date) >= new Date(dateFrom)); if (dateTo) list = list.filter(tr => new Date(tr.date) <= new Date(dateTo)); }
    return list.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [transactions, selectedAccountId, period, dateFrom, dateTo]);
  const acc = accounts.find(a => a.id === selectedAccountId);
  const format = (val: number) => `${currency.symbol} ${val.toLocaleString(lang, { minimumFractionDigits: 2 })}`;
  return (
    <div className="animate-in fade-in duration-500 space-y-8">
      <div className="hidden print:block mb-10 border-b-4 border-blue-600 pb-8"><div className="flex justify-between items-start mb-6"><div><h1 className="text-4xl font-black text-blue-600 tracking-tighter mb-2">FinSense</h1><p className="text-sm font-bold text-gray-500 uppercase tracking-widest">Account Statement</p></div><div className="text-right"><p className="text-lg font-black text-gray-900">{profile?.name || 'User'}</p><p className="text-sm font-bold text-gray-500">{profile?.email}</p><p className="text-xs text-gray-400 mt-2">Generated {new Date().toLocaleDateString(lang)}</p></div></div><div className="grid grid-cols-2 gap-8 mt-12"><div className="border-l-4 border-gray-100 pl-4"><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Account</p><p className="text-xl font-bold text-gray-800">{acc?.name || '---'}</p></div><div className="border-l-4 border-blue-100 pl-4"><p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Period</p><p className="text-xl font-bold text-blue-600 uppercase">{period}</p></div></div></div>
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm relative overflow-hidden print:border-none print:p-0">
        <div className="flex justify-between items-start mb-8 print:hidden"><div className="grid grid-cols-1 md:grid-cols-2 gap-8 flex-1">
          <div><label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.select_account}</label><select value={selectedAccountId} onChange={(e) => setSelectedAccountId(e.target.value)} className="w-full bg-gray-50 border p-4 rounded-2xl outline-none font-bold text-sm">{accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}</select></div>
          <div><label className="text-[10px] font-black text-gray-900 uppercase tracking-widest block mb-3">{t.period}</label><div className="flex flex-wrap gap-2">{(['current', 'last', 'custom'] as const).map(p => <button key={p} onClick={() => setPeriod(p)} className={`px-4 py-3 rounded-xl text-xs font-bold border ${period === p ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-50 text-gray-400'}`}>{(t as any)[p] || p}</button>)}</div></div>
        </div><button onClick={() => window.print()} className="ms-4 p-4 bg-gray-50 rounded-2xl text-gray-400 hover:text-blue-600 transition-all print:hidden"><Printer className="w-5 h-5" /></button></div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-6 bg-blue-50/50 rounded-3xl border border-blue-100 print:bg-transparent print:border-none print:px-0 print:mb-8"><div className="print:border-l-2 print:pl-4"><p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1 print:text-gray-400">{t.summary}</p><p className="text-sm font-bold text-blue-900 print:text-gray-900">{acc?.name || '---'}</p></div><div className="print:border-l-2 print:pl-4"><p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1 print:text-blue-400">{t.available_funds}</p><p className="text-base font-black text-blue-600 print:text-2xl">{format(acc?.balance || 0)}</p></div></div>
      </div>
      <TransactionList transactions={filteredTransactions} lang={lang} onDelete={onDelete} />
    </div>
  );
};

const StatCard = ({ title, value, trend, trendType, icon, isDebt, onClick }: any) => (
  <div onClick={onClick} className={`bg-white p-6 lg:p-8 rounded-[2.5rem] border border-gray-100 flex items-start justify-between shadow-sm hover:shadow-lg transition-all cursor-pointer group ${isDebt ? 'border-rose-50' : ''}`}>
