          <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold text-sm" placeholder={tStr.account_name} />
          <select value={type} onChange={e => setType(e.target.value as AccountType)} className="w-full border p-4 rounded-2xl bg-gray-50 outline-none font-bold text-sm">{['Checking', 'Savings', 'Credit Card', 'Investment', 'Cash'].map(at => <option key={at} value={at}>{(tStr.account_types as any)[at]}</option>)}</select>
