const AccountsView = ({ accounts, formatMoney, lang, onAddClick, onEditClick, onDelete }: any) => {
  const tStr = translations[lang];
  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
